window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-97"]=[{"id":"set2-mdV4N4Me","fingerprint":"f793bdff8cbab4b5","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt nivelurile la care este organizat răspunsul de apărare al complexului dentino-pulpar?","options":[{"id":"A","text":"La joncțiunea dentină-pulpă, unde se constituie dentina terțiară."},{"id":"B","text":"În interiorul pulpei, prin apariția reacției inflamatorii."},{"id":"C","text":"La nivelul ligamentului parodontal, prin îngroșarea acestuia."},{"id":"D","text":"La joncțiunea smalț-dentină, prin formarea dentinei primare."},{"id":"E","text":"La nivel dentinar, prin producerea de scleroză tubulară."}],"correct":["A","B","E"],"pages":[104],"source":"set-2"},{"id":"set2-BFfGhxeI","fingerprint":"541b89a3b22a8245","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce forme clinice sunt incluse în categoria pulpitelor reversibile?","options":[{"id":"A","text":"Pulpita cronică închisă și cea deschisă."},{"id":"B","text":"Hiperemia preinflamatorie și pulpita acută seroasă parțială."},{"id":"C","text":"Pulpita seroasă coronară și cea corono-radiculară."},{"id":"D","text":"Pulpita seroasă totală și pulpitele purulente."},{"id":"E","text":"Granulomul intern Palazzi și pulpita granulomatoasă."}],"correct":["B"],"pages":[104],"source":"set-2"},{"id":"set2-IfHilte0","fingerprint":"dd00f64b91ead869","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect pulpita reversibilă?","options":[{"id":"A","text":"Pulpa dentară își poate recupera starea de sănătate dacă se elimină cauza."},{"id":"B","text":"Se caracterizează prin durere intensă, care nu cedează la îndepărtarea stimulului."},{"id":"C","text":"Efectele iritanților bacterieni pot fi anulate printr-o atitudine terapeutică conservativă corectă."},{"id":"D","text":"Indiferent de tratamentele aplicate, pulpa dentară nu își recapătă starea de sănătate."},{"id":"E","text":"Este caracterizată de o sensibilitate termică localizată și tranzitorie."}],"correct":["A","C","E"],"pages":[104],"source":"set-2"},{"id":"set2-koraXmZF","fingerprint":"972dc6af314200d9","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Conform clasificării anatomo-clinice, cum este denumită pulpita cronică închisă hiperplazică?","options":[{"id":"A","text":"Pulpită ulceroasă"},{"id":"B","text":"Pulpită seroasă totală"},{"id":"C","text":"Granulom intern Palazzi"},{"id":"D","text":"Pulpită granulomatoasă polipoasă"},{"id":"E","text":"Hiperemie preinflamatorie"}],"correct":["C"],"pages":[104],"source":"set-2"},{"id":"set2-rSZidE1A","fingerprint":"66a019d812eb5739","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"În ce situații clinice, în ciuda existenței unei îmbolnăviri pulpare, poate fi întâlnită absența simptomatologiei?","options":[{"id":"A","text":"În pulpitele cronice."},{"id":"B","text":"În pulpita acută seroasă parțială."},{"id":"C","text":"În necroza pulpară necomplicată."},{"id":"D","text":"În pulpita acută purulentă."},{"id":"E","text":"În hiperemia preinflamatorie."}],"correct":["A","C"],"pages":[104],"source":"set-2"},{"id":"set2-NoBru8p5","fingerprint":"75664a5b7626a4ef","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este mecanismul principal prin care procesele carioase induc modificări regresive la nivelul prelungirilor odontoblastice?","options":[{"id":"A","text":"Prin întreruperea vascularizației de tip terminal a pulpei dentare."},{"id":"B","text":"Prin difuzia toxinelor bacteriene în canaliculele dentinare."},{"id":"C","text":"Prin activarea sistemului nervos bine reprezentat al pulpei."},{"id":"D","text":"Prin exercitarea unei presiuni directe asupra țesutului pulpar."},{"id":"E","text":"Prin stimularea formării excesive de dentină terțiară."}],"correct":["B"],"pages":[104],"source":"set-2"},{"id":"set2-agXgETSA","fingerprint":"7f0e102b4bebd3ce","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care dintre următoarele particularități anatomice conferă pulpei dentare o vulnerabilitate crescută?","options":[{"id":"A","text":"Pereții dentinari permeabili la agenții patogeni."},{"id":"B","text":"Un sistem nervos slab reprezentat."},{"id":"C","text":"Prezența unei vascularizații de tip terminal."},{"id":"D","text":"Lipsa rapoartelor cu parodonțiul."},{"id":"E","text":"Adăpostirea într-un spațiu cu pereți elastici."}],"correct":["C"],"pages":[104],"source":"set-2"},{"id":"set2-mXYf00Jn","fingerprint":"1d311f86e6b2ddee","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următorii sunt considerați factori externi responsabili de declanșarea pulpitelor?","options":[{"id":"A","text":"Factori intercurenți"},{"id":"B","text":"Acizii și bazele"},{"id":"C","text":"Procesele carioase"},{"id":"D","text":"Supraîncălzirea în timpul preparării cavității"},{"id":"E","text":"Fungii și virusurile"}],"correct":["B","C","D","E"],"pages":[105],"source":"set-2"},{"id":"set2-A9qrtA9F","fingerprint":"5b560f9a6ed2b04d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce efect specific poate avea supraîncălzirea dentinei în timpul preparării unei cavități?","options":[{"id":"A","text":"Secționarea prelungirilor odontoblastice."},{"id":"B","text":"Instalarea unei pulpite retrograde."},{"id":"C","text":"Producerea de microhemoragii și dezintegrarea odontoblaștilor."},{"id":"D","text":"Aspirarea odontoblaștilor în canaliculele dentinare."},{"id":"E","text":"Declanșarea unui răspuns inflamator limitat la pulpa coronară."}],"correct":["C"],"pages":[105],"source":"set-2"},{"id":"set2-zI4g3BLY","fingerprint":"67ca7aab8f5a0cfc","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile morfopatologice ale hiperemiei pulpare?","options":[{"id":"A","text":"Odontoblaști măriți de volum."},{"id":"B","text":"Plasmexodie și vasodilatație."},{"id":"C","text":"Vase sanguine dilatate și marginație leucocitară."},{"id":"D","text":"Acumulări de eritrocite."},{"id":"E","text":"Este un stadiu inflamator cronic."}],"correct":["A","C","D"],"pages":[105],"source":"set-2"},{"id":"set2-a9io-2gl","fingerprint":"092e106867d50a97","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici are durerea în cazul hiperemiei pulpare?","options":[{"id":"A","text":"Are o durată de câteva minute."},{"id":"B","text":"Este o durere localizată și de intensitate moderată."},{"id":"C","text":"Este de intensitate severă."},{"id":"D","text":"Este o durere provocată de agenți termici (rece) și chimici (dulce)."},{"id":"E","text":"Este o durere generalizată, iradiantă."}],"correct":["A","B","D"],"pages":[105],"source":"set-2"},{"id":"set2-S5zHkvcd","fingerprint":"c3a56d06b876ecad","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care este evoluția posibilă a unei hiperemii pulpare?","options":[{"id":"A","text":"Necesită în mod obligatoriu amputație vitală."},{"id":"B","text":"Se transformă exclusiv în pulpită cronică."},{"id":"C","text":"Poate reveni la starea de \"restitutio ad integrum\"."},{"id":"D","text":"Evoluează întotdeauna spre o pulpită acută."},{"id":"E","text":"Poate evolua spre o pulpită acută sau cronică."}],"correct":["C","E"],"pages":[105],"source":"set-2"},{"id":"set2-6vTZWNpv","fingerprint":"9d8d0da18d4e67f1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În ce condiție este pulpita acută seroasă parțială considerată o afecțiune reversibilă?","options":[{"id":"A","text":"Când este tratată prin extirpare vitală."},{"id":"B","text":"Când se observă morfopatologic marginație leucocitară."},{"id":"C","text":"Când procesul inflamator este limitat la pulpa coronară."},{"id":"D","text":"Când durerea este provocată doar de stimuli termici reci."},{"id":"E","text":"Când diagnosticul diferențial se face cu hiperestezia."}],"correct":["C"],"pages":[105],"source":"set-2"},{"id":"set2-k3sXg254","fingerprint":"2ad22af9031785b8","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce elemente stau la baza diagnosticului pozitiv de hiperemie pulpară?","options":[{"id":"A","text":"Doar prezența unui tratament restaurativ recent."},{"id":"B","text":"Diagnosticul diferențial cu hipersensibilitatea."},{"id":"C","text":"Caracterele durerii și un eventual tratament restaurativ recent."},{"id":"D","text":"Evoluția spre \"restitutio ad integrum\"."},{"id":"E","text":"Vasodilatația și plasmexodia observate morfopatologic."}],"correct":["C"],"pages":[105],"source":"set-2"},{"id":"set2-nyvPECEw","fingerprint":"985b7a100acf1ead","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este o caracteristică distinctivă a durerii în pulpita acută seroasă parțială, spre deosebire de cea totală?","options":[{"id":"A","text":"Este descrisă metaforic ca \"turbarea dinților\"."},{"id":"B","text":"Cedează la administrarea de antialgice."},{"id":"C","text":"Este o durere spontană."},{"id":"D","text":"Este o durere continuă și insuportabilă."},{"id":"E","text":"Iradiază în regiunea temporală și orbitară."}],"correct":["B"],"pages":[106],"source":"set-2"},{"id":"set2-TKSgE6zc","fingerprint":"dcc22494e721cdf4","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele modificări morfopatologice sunt caracteristice pulpitei acute seroase parțiale?","options":[{"id":"A","text":"Creșterea permeabilității vasculare generalizate."},{"id":"B","text":"Marginație leucocitară."},{"id":"C","text":"Degenerescența fibroblaștilor."},{"id":"D","text":"Vacuolizări și acumulări lipoidice la nivelul odontoblaștilor."},{"id":"E","text":"Demielinizarea fibrelor nervoase."}],"correct":["B","C","D"],"pages":[106],"source":"set-2"},{"id":"set2-5a3kRmzX","fingerprint":"ecd2c6aba6d1d6d1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este prima formă de pulpită considerată ireversibilă, a cărei evoluție naturală este spre necroză?","options":[{"id":"A","text":"Pulpita purulentă"},{"id":"B","text":"Niciuna dintre variantele de mai sus"},{"id":"C","text":"Pulpita acută seroasă parțială"},{"id":"D","text":"Hiperemia preinflamatorie"},{"id":"E","text":"Pulpita acută seroasă totală"}],"correct":["E"],"pages":[106],"source":"set-2"},{"id":"set2-id2ifRAa","fingerprint":"7917e93108c36059","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici ale durerii sunt specifice pulpitei acute seroase totale?","options":[{"id":"A","text":"Este o durere lancinantă și continuă."},{"id":"B","text":"Se calmează prompt la administrarea de antialgice."},{"id":"C","text":"Iradiază în regiuni precum cea temporală, orbitară sau submandibulară."},{"id":"D","text":"Nu depășește linia mediană."},{"id":"E","text":"Este o durere localizată strict la dintele cauzal."}],"correct":["A","C","D"],"pages":[106],"source":"set-2"},{"id":"set2-LqZ6s9cE","fingerprint":"de200add067faa31","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este mecanismul fiziopatologic principal care declanșează durerea spontană și violentă în pulpita acută seroasă totală?","options":[{"id":"A","text":"Vasodilatație și plasmexodie strict la nivelul pulpei coronare."},{"id":"B","text":"Acumularea de exudat seros, care duce la creșterea presiunii intratisulare, acidoză locală și compresiunea fibrelor nervoase."},{"id":"C","text":"Demielinizarea fibrelor nervoase ca proces inflamator primar."},{"id":"D","text":"Oprirea metabolismului odontoblaștilor, cu acumulări lipoidice."},{"id":"E","text":"Marginația leucocitară și degenerescența fibroblaștilor."}],"correct":["B"],"pages":[106],"source":"set-2"},{"id":"set2-olqYS9aa","fingerprint":"d7c0e5843420644d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele proceduri terapeutice aplicate în pulpita acută seroasă parțială au ca scop păstrarea vitalității pulpare?","options":[{"id":"A","text":"Doar monitorizarea clinică"},{"id":"B","text":"Coafajul direct"},{"id":"C","text":"Extirparea vitală"},{"id":"D","text":"Niciuna dintre variantele de mai sus"},{"id":"E","text":"Amputația vitală"}],"correct":["B","E"],"pages":[106],"source":"set-2"},{"id":"set2-VfPxsNt1","fingerprint":"2c588a76525ae17d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile durerii în pulpita acută purulentă?","options":[{"id":"A","text":"Are un caracter pulsatil."},{"id":"B","text":"Apare cu precădere în timpul zilei, fiind calmată de repausul nocturn."},{"id":"C","text":"Este diminuată de aplicarea locală de căldură."},{"id":"D","text":"Crizele dureroase sunt spontane și durează câteva ore."},{"id":"E","text":"Este violentă și exacerbată de creșterea fluxului sanguin."}],"correct":["A","D","E"],"pages":[107],"source":"set-2"},{"id":"set2-j_9adW2H","fingerprint":"bfde87b0d3078684","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce modificări morfopatologice sunt specifice pulpitei acute purulente?","options":[{"id":"A","text":"Formarea de microabcese localizate sau flegmon pulpar generalizat."},{"id":"B","text":"Apariția unei reacții congestive care cuprinde spațiul periapical."},{"id":"C","text":"Formarea de țesut de granulație cu tendință crescută la vindecare."},{"id":"D","text":"Prezența unei ulcerații la suprafața pulpei, acoperită de depozite de fibrină."},{"id":"E","text":"Dezagregarea celulelor, prezența fragmentelor de nucleu și a încărcărilor lipidice."}],"correct":["A","B","E"],"pages":[107],"source":"set-2"},{"id":"set2-yAiRj58R","fingerprint":"4d2c00a8408060ca","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele semne clinice este un element cheie în diagnosticul diferențial al pulpitei acute seroase difuze cu parodontita apicală acută seroasă?","options":[{"id":"A","text":"Testele de vitalitate negative."},{"id":"B","text":"Durerea exacerbată la cald și diminuată la rece."},{"id":"C","text":"Caracterul pulsatil al durerii."},{"id":"D","text":"Senzația de egresiune a dintelui."},{"id":"E","text":"Prezența unei picături de puroi la deschiderea camerei pulpare."}],"correct":["A","D"],"pages":[107],"source":"set-2"},{"id":"set2-jGII1aTZ","fingerprint":"dced3f032ddc1f99","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Conform clasificării anatomo-clinice, care dintre următoarele este considerată o formă de pulpită cronică deschisă?","options":[{"id":"A","text":"Pulpita cronică proprie-zisă."},{"id":"B","text":"Pulpita acută seroasă."},{"id":"C","text":"Pulpita cronică polipoasă."},{"id":"D","text":"Pulpita cronică ulceroasă."},{"id":"E","text":"Pulpita cronică hiperplazică."}],"correct":["C","D"],"pages":[107],"source":"set-2"},{"id":"set2-T0zVWp6M","fingerprint":"42cb607153de38e7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care este relația dintre reactivitatea individuală și tipul de pulpită cronică deschisă care se dezvoltă?","options":[{"id":"A","text":"Pulpita polipoasă este asociată cu o bună reactivitate generală."},{"id":"B","text":"Pulpita ulceroasă se dezvoltă de regulă la pacienții cu o capacitate de apărare individuală scăzută."},{"id":"C","text":"O capacitate de apărare individuală scăzută este de obicei asociată cu pulpita polipoasă."},{"id":"D","text":"Reactivitatea individuală nu influențează evoluția procesului inflamator cronic în pulpitele deschise."},{"id":"E","text":"O bună reactivitate generală, specifică tinerilor, favorizează dezvoltarea pulpitei ulceroase."}],"correct":["A","B"],"pages":[107],"source":"set-2"},{"id":"set2-4eydiH9E","fingerprint":"e73433ccf43d6ce0","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici morfopatologice sunt prezente în pulpita cronică deschisă ulceroasă?","options":[{"id":"A","text":"Suprafața pulpară prezintă o ulcerație acoperită de depozite de fibrină."},{"id":"B","text":"Suprafața pulpară ulcerată este formată din țesut de granulație și are o tendință scăzută la vindecare."},{"id":"C","text":"Nu există modificări morfopatologice vizibile la nivelul pulpei."},{"id":"D","text":"Transformarea purulentă a pulpei sub formă de flegmon pulpar."},{"id":"E","text":"Ulcerația este înconjurată de zone de necroză și un infiltrat inflamator cu PMN, bacterii și resturi alimentare."}],"correct":["A","B","E"],"pages":[107],"source":"set-2"},{"id":"set2-QZk8OIdQ","fingerprint":"618ec47f8d16c954","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este simptomatologia subiectivă caracteristică pulpitei cronice deschise ulceroase?","options":[{"id":"A","text":"Senzație de egresiune a dintelui și congestia mucoasei vestibulare."},{"id":"B","text":"Durere violentă, cu caracter pulsatil, care apare în crize spontane."},{"id":"C","text":"Stare generală alterată."},{"id":"D","text":"Durere exacerbată de stimuli reci și diminuată de căldură."},{"id":"E","text":"Afecțiunea este în general nedureroasă, pacientul acuzând o jenă la masticație."}],"correct":["E"],"pages":[107],"source":"set-2"},{"id":"set2-s_5gPCDZ","fingerprint":"f8e997473119eb89","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele elemente clinice susțin diagnosticul pozitiv de pulpită cronică deschisă ulceroasă?","options":[{"id":"A","text":"Lipsa durerii."},{"id":"B","text":"Absența sângerării la înțeparea pulpei cu sonda."},{"id":"C","text":"Percuția în ax este pozitivă, indicând o inflamație periapicală."},{"id":"D","text":"Teste de vitalitate pozitive la intensități mari ale stimulului."},{"id":"E","text":"Prezența unei formațiuni polipoase care ocupă camera pulpară."}],"correct":["A","D"],"pages":[108],"source":"set-2"},{"id":"set2-Gm2WczbX","fingerprint":"ff1cd3516c2829c3","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici morfopatologice și clinice sunt specifice pulpitei cronice deschise polipoase?","options":[{"id":"A","text":"Baza de inserție a polipului este întotdeauna la nivelul gingiei interdentare."},{"id":"B","text":"Sângerarea la masticație este un simptom subiectiv."},{"id":"C","text":"Formațiunea polipoasă este o proliferare a țesutului de granulație."},{"id":"D","text":"La înțeparea cu sonda, polipul este dureros pe toată suprafața sa."},{"id":"E","text":"Suprafața polipului poate fi acoperită cu epiteliu pavimentos multistratificat."}],"correct":["B","C","E"],"pages":[108],"source":"set-2"},{"id":"set2-yq8Yfzqa","fingerprint":"a02061ed3fec8ede","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este principalul criteriu de diagnostic diferențial între un polip pulpar și un polip gingival?","options":[{"id":"A","text":"Prezența sângerării la atingere."},{"id":"B","text":"Baza de inserție a formațiunii."},{"id":"C","text":"Răspunsul la testele de vitalitate."},{"id":"D","text":"Dimensiunea cavității carioase."},{"id":"E","text":"Culoarea formațiunii tisulare."}],"correct":["B"],"pages":[108],"source":"set-2"},{"id":"set2-YAdXA_91","fingerprint":"6cb067a82bc8240e","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect pulpitele cronice închise?","options":[{"id":"A","text":"Histopatologic, se caracterizează prin prezența țesutului de granulație."},{"id":"B","text":"Sunt forme de pulpită frecvent întâlnite."},{"id":"C","text":"Evoluția lor este de obicei lentă și asimptomatică."},{"id":"D","text":"Sunt întotdeauna dureroase la percuția în ax."},{"id":"E","text":"Camera pulpară este larg deschisă prin procesul carios."}],"correct":["A","C"],"pages":[108],"source":"set-2"},{"id":"set2-vPFnQTkm","fingerprint":"53a4dbd7de531767","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce factor local este considerat a fi un stimul pentru dezvoltarea și creșterea unui polip pulpar?","options":[{"id":"A","text":"Prezența țesutului de granulație în camera pulpară."},{"id":"B","text":"Epitelizarea suprafeței pulpei expuse."},{"id":"C","text":"Muchia de dentină ascuțită de la nivelul deschiderii camerei pulpare."},{"id":"D","text":"Sângerarea abundentă a țesutului pulpar."},{"id":"E","text":"Acumularea de resturi alimentare în cavitatea carioasă."}],"correct":["C"],"pages":[108],"source":"set-2"},{"id":"set2---btO4SE","fingerprint":"8faa1f181b608742","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Prin ce se diferențiază necroza și gangrena pulpară de pulpita cronică deschisă ulceroasă în cadrul diagnosticului diferențial?","options":[{"id":"A","text":"Prin prezența unei camere pulpare închise."},{"id":"B","text":"Prin prezența durerii spontane de intensitate mare."},{"id":"C","text":"Prin lipsa de sensibilitate și absența sângerării la sondare."},{"id":"D","text":"Prin percuția în ax întotdeauna negativă."},{"id":"E","text":"Prin răspunsul pozitiv la testele de vitalitate."}],"correct":["C"],"pages":[108],"source":"set-2"},{"id":"set2-s_EDEpmA","fingerprint":"7f5b99b25f967b4d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile clinice și de diagnostic ale pulpitei cronice închise propriu-zise?","options":[{"id":"A","text":"Prezența unei sângerări abundente la deschiderea camerei pulpare este un element de diagnostic pozitiv."},{"id":"B","text":"Pacientul este de obicei asimptomatic."},{"id":"C","text":"La deschiderea camerei pulpare, sângerarea este minimă sau absentă."},{"id":"D","text":"La examenul obiectiv se constată o cavitate carioasă cu dentină ușor colorată pe fundul acesteia."},{"id":"E","text":"Testele de vitalitate sunt negative sau pozitive la intensități scăzute."}],"correct":["A","B","D"],"pages":[109],"source":"set-2"},{"id":"set2-Gi-b75Na","fingerprint":"140423a142d142f9","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce semn radiologic este caracteristic pentru pulpita cronică închisă hiperplazică (granulomul intern Palazzi)?","options":[{"id":"A","text":"Absența oricărei modificări la nivelul conturului spațiului endodontic."},{"id":"B","text":"Încapsularea zonei pulpare afectate de o membrană de țesut conjunctiv vizibilă radiologic."},{"id":"C","text":"O zonă de resorbție radiculară externă cu aspect asimetric."},{"id":"D","text":"Modificarea conturului camerei pulpare sau al canalului radicular, cu aspect simetric."},{"id":"E","text":"O lărgire uniformă a spațiului periodontal în jurul apexului."}],"correct":["D"],"pages":[109],"source":"set-2"},{"id":"set2-yMF8BBP_","fingerprint":"b2a77f5d70710962","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la diagnosticul diferențial al pulpitei cronice închise sunt corecte?","options":[{"id":"A","text":"Pulpita cronică deschisă ulceroasă este un diagnostic diferențial pentru pulpita cronică închisă propriu-zisă."},{"id":"B","text":"Granulomul intern Palazzi se diferențiază de resorbția radiculară externă prin aspectul simetric al zonei resorbtive."},{"id":"C","text":"Apariția unei \"pete roz\" coronare exclude diagnosticul de pulpită cronică închisă hiperplazică."},{"id":"D","text":"Pulpita cronică închisă propriu-zisă nu necesită diferențiere de necroza pulpară."},{"id":"E","text":"Ambele forme de pulpită cronică închisă (propriu-zisă și hiperplazică) au ca diagnostic diferențial necroza pulpară."}],"correct":["A","B","E"],"pages":[109],"source":"set-2"},{"id":"set2-mTgyg-Zo","fingerprint":"a2bdf550679b53bc","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce procese morfopatologice caracterizează pulpita cronică închisă hiperplazică (granulomatoasă)?","options":[{"id":"A","text":"Țesutul de granulație resoarbe dentina într-o manieră circulară și expansivă."},{"id":"B","text":"Procesul inflamator este strict delimitat la pulpa coronară, fără afectarea dentinei."},{"id":"C","text":"O membrană de țesut conjunctiv încapsulează zona pulpară afectată acut."},{"id":"D","text":"Țesutul pulpar este substituit de țesut de granulație."},{"id":"E","text":"Dentinoclastele formează lacune în dentina afectată de procesul resorbtiv."}],"correct":["A","D","E"],"pages":[109],"source":"set-2"},{"id":"set2-ReIL-bbJ","fingerprint":"4543967f314db315","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"În ce constă procedura de pulpotomie vitală (amputație vitală)?","options":[{"id":"A","text":"Îndepărtarea pulpei radiculare și menținerea celei coronare pentru a stimula vindecarea."},{"id":"B","text":"Menținerea integrală a pulpei coronare și radiculare, cu aplicarea unui material de protecție."},{"id":"C","text":"Îndepărtarea porțiunii coronare a pulpei și menținerea integrală a celei radiculare."},{"id":"D","text":"Aplicarea unui material corespunzător peste pulpa radiculară restantă în scop de protecție și vindecare."},{"id":"E","text":"Extirparea completă a țesutului pulpar, atât din camera pulpară, cât și din canalele radiculare."}],"correct":["C","D"],"pages":[109],"source":"set-2"},{"id":"set2-Zyfonyul","fingerprint":"5c36ebc4ee3b8aa7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este o dificultate specifică menționată în tratamentul pulpitei cronice închise hiperplazice?","options":[{"id":"A","text":"Identificarea dificilă a orificiilor canalelor radiculare din cauza calcificărilor."},{"id":"B","text":"Simptomatologia absentă face ca pacientul să nu accepte tratamentul."},{"id":"C","text":"Sângerarea abundentă care împiedică realizarea corectă a preparării canalului."},{"id":"D","text":"Pericolul de fractură corono-radiculară în timpul instrumentării canalului."},{"id":"E","text":"Necesitatea monitorizării radiologice pe termen lung din cauza riscului de recidivă."}],"correct":["D"],"pages":[109],"source":"set-2"},{"id":"set2-fLFMUr4f","fingerprint":"b3c8a24383126462","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt indicațiile pentru realizarea unei pulpotomii vitale?","options":[{"id":"A","text":"Tratamentul simptomatic al pulpitelor ireversibile, ca intervenție conservativă de urgență."},{"id":"B","text":"Deschideri accidentale extinse ale camerei pulpare unde coafajul direct clasic nu este posibil."},{"id":"C","text":"Tratamentul definitiv al dinților pluriradiculari în ședința de urgență."},{"id":"D","text":"Tratamentul de elecție pentru pulpitele cronice."},{"id":"E","text":"Pulpite retrograde și luxații dentare."}],"correct":["A","B"],"pages":[110],"source":"set-2"},{"id":"set2-pG30KOQ-","fingerprint":"1050ab6f3fa31164","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce definește pulpotomia?","options":[{"id":"A","text":"Aplicarea unui material de coafaj direct pe pulpa expusă accidental."},{"id":"B","text":"Amputația chirurgicală a porțiunii coronare a pulpei expuse."},{"id":"C","text":"Îndepărtarea chirurgicală a pulpei coronare și radiculare după anestezie."},{"id":"D","text":"Îndepărtarea completă a dentinei alterate și obturarea temporară a cavității."},{"id":"E","text":"Eliminarea tavanului camerei pulpare și irigarea cu hipoclorit de sodiu."}],"correct":["B"],"pages":[110],"source":"set-2"},{"id":"set2-RPtFdGOP","fingerprint":"7bd963d15199439c","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce proprietăți trebuie să îndeplinească materialele utilizate pentru coafarea pulpei radiculare remanente în cadrul unei pulpotomii?","options":[{"id":"A","text":"Să fie biocompatibile."},{"id":"B","text":"Să aibă proprietăți antimicrobiene."},{"id":"C","text":"Să fie radioopace pentru a permite monitorizarea."},{"id":"D","text":"Să realizeze o bună sigilare."},{"id":"E","text":"Să fie neapărat fotopolimerizabile."}],"correct":["A","B","D"],"pages":[110],"source":"set-2"},{"id":"set2-cyygn-BG","fingerprint":"d65d00f869a8f5a2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este grosimea stratului de ciment disilicat de calciu (MTA, Biodentina) recomandată în protocolul de pulpotomie la dinții permanenți?","options":[{"id":"A","text":"Exact 3 mm."},{"id":"B","text":"Aproximativ 0.5 mm."},{"id":"C","text":"Peste 3 mm."},{"id":"D","text":"Aproximativ 1-2 mm."},{"id":"E","text":"Mai puțin de 1 mm."}],"correct":["D"],"pages":[110],"source":"set-2"},{"id":"set2-ubdejQSH","fingerprint":"7bf246f17dc9953f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În cadrul unei pulpotomii la un dinte permanent, de ce se recomandă realizarea restaurării coronare în aceeași ședință?","options":[{"id":"A","text":"Pentru a asigura o hemostază superioară a bontului pulpar."},{"id":"B","text":"Pentru a reduce costurile totale ale tratamentului."},{"id":"C","text":"Pentru a verifica imediat vitalitatea pulpei remanente."},{"id":"D","text":"Pentru a permite priza completă a materialului de coafaj pulpar."},{"id":"E","text":"Pentru a scădea riscul de contaminare prin reintervenție în ședințe ulterioare."}],"correct":["E"],"pages":[110],"source":"set-2"},{"id":"set2-XE-MP0Wb","fingerprint":"49649f3a27fd99c7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente definesc succesul unui tratament de pulpotomie la monitorizarea pe termen lung?","options":[{"id":"A","text":"Prezența unei obturații coronare temporare necompresive."},{"id":"B","text":"Realizarea tratamentului endodontic complet în decurs de o lună."},{"id":"C","text":"Obliterarea radiologică completă a canalelor radiculare."},{"id":"D","text":"Absența simptomatologiei pulpare și periapicale."},{"id":"E","text":"Menținerea vitalității pulpei."}],"correct":["D","E"],"pages":[110],"source":"set-2"},{"id":"set2-gObFJa1s","fingerprint":"2daaaf156ebd1693","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt pașii specifici descriși pentru realizarea unei pulpotomii de urgență la dinții pluriradiculari?","options":[{"id":"A","text":"Aplicarea unui strat de MTA și a unei restaurări definitive în aceeași ședință."},{"id":"B","text":"Îndepărtarea pulpei cu un excavator până la nivelul emergenței canalelor radiculare."},{"id":"C","text":"Utilizarea unei freze Gates-Glidden pentru a secționa pulpa la intrarea în canale și a reduce hemoragia."},{"id":"D","text":"Aplicarea unei paste pe bază de hidroxid de calciu și o obturație coronară temporară."},{"id":"E","text":"Finalizarea tratamentului endodontic complet în aceeași ședință de urgență."}],"correct":["B","C","D"],"pages":[110],"source":"set-2"},{"id":"set2-iAHU01Pn","fingerprint":"ce3644b21a5c7e9d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce reprezintă pulpectomia vitală?","options":[{"id":"A","text":"O intervenție de urgență menită să reducă durerea în pulpitele ireversibile acute."},{"id":"B","text":"Îndepărtarea chirurgicală a pulpei coronare și radiculare după insensibilizarea acesteia prin anestezie."},{"id":"C","text":"Coafarea pulpei radiculare remanente cu materiale bioceramice."},{"id":"D","text":"O procedură indicată doar în cazul deschiderilor accidentale ale camerei pulpare."},{"id":"E","text":"Amputația chirurgicală exclusiv a porțiunii coronare a pulpei expuse."}],"correct":["B"],"pages":[110],"source":"set-2"},{"id":"set2-WxS61uGS","fingerprint":"511733c70a0eb471","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Printre indicațiile pulpectomiei vitale se numără:","options":[{"id":"A","text":"Deschideri accidentale extinse ale camerei pulpare unde nu se poate realiza coafaj direct."},{"id":"B","text":"Pulpitele acute și cronice."},{"id":"C","text":"Dinți situați în focare de fractură."},{"id":"D","text":"Dinți aflați în vecinătatea unor formațiuni patologice precum chisturi maxilare sau osteomielite."},{"id":"E","text":"Tratamentul simptomatic de urgență al pulpitelor ireversibile."}],"correct":["A","B","C","D"],"pages":[110],"source":"set-2"},{"id":"set2-K4LkC_og","fingerprint":"abb5b86ee5fc0493","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele sunt considerate categorii de contraindicații ale tratamentului endodontic?","options":[{"id":"A","text":"Afecțiuni generale"},{"id":"B","text":"Stări fiziologice"},{"id":"C","text":"Afecțiuni locoregionale"},{"id":"D","text":"Suprainstrumentarea canalului radicular"},{"id":"E","text":"Cooperarea deficitară"}],"correct":["A","B","C","E"],"pages":[111],"source":"set-2"},{"id":"set2-YB8VnwDN","fingerprint":"23e4d4c9ffea1689","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Conform secvenței timpilor operatori ai unui tratament endodontic, ce acțiune se realizează imediat după măsurarea lungimii de lucru a canalului radicular?","options":[{"id":"A","text":"Reperarea orificiilor de emergență ale canalelor radiculare"},{"id":"B","text":"Preparația chemo-mecanică"},{"id":"C","text":"Izolarea dintelui"},{"id":"D","text":"Deschiderea camerei pulpare"},{"id":"E","text":"Obturația de durată a canalului radicular"}],"correct":["B"],"pages":[111],"source":"set-2"},{"id":"set2-5ok1BDs8","fingerprint":"824a9da8ea358e46","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele sunt considerate cauze locale de hemoragie în timpul unui tratament endodontic?","options":[{"id":"A","text":"Suprainstrumentarea"},{"id":"B","text":"Extirparea incompletă"},{"id":"C","text":"Afecțiuni hepatice grave"},{"id":"D","text":"Perforarea podelei camerei pulpare"},{"id":"E","text":"Hemofilia"}],"correct":["A","B","D"],"pages":[111],"source":"set-2"},{"id":"set2-bUuY_Jwx","fingerprint":"32c14aefc12a1a61","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce caracteristică definește necroza pulpară în condiții aseptice?","options":[{"id":"A","text":"Este mortificarea aseptică a pulpei în condițiile camerei pulpare închise."},{"id":"B","text":"Determină întotdeauna o inflamație imediată în țesutul periapical."},{"id":"C","text":"Este o mortificare septică a pulpei sub influența germenilor anaerobi."},{"id":"D","text":"Apare ca urmare a extinderii bacteriilor în spațiul periodontal."},{"id":"E","text":"Este o afecțiune în care pulpa este lipsită de inervație, dar păstrează circulația sanguină."}],"correct":["A"],"pages":[111],"source":"set-2"},{"id":"set2-CCdSCG-i","fingerprint":"0df8b06e9831534b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este consecința clinică a extinderii bacteriilor din spațiul endodontic al unui dinte cu necroză pulpară la nivelul spațiului periodontal?","options":[{"id":"A","text":"Ruperea pachetului vascular pulpar."},{"id":"B","text":"Apariția unor spasme vasculare prelungite."},{"id":"C","text":"Apariția durerilor spontane și la percuție."},{"id":"D","text":"Dezvoltarea unei necroze de lichefacție aseptică."},{"id":"E","text":"Menținerea stării asimptomatice a afecțiunii."}],"correct":["C"],"pages":[111],"source":"set-2"},{"id":"set2-nYTeWIdW","fingerprint":"5245022763aa19f8","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următorii factori sunt implicați în etiopatogenia locală a necrozei pulpare?","options":[{"id":"A","text":"Traumatisme de intensitate mică și repetată"},{"id":"B","text":"Germenii microbieni"},{"id":"C","text":"Inflamația pulpară acută sau cronică"},{"id":"D","text":"Diatezele hemoragipare"},{"id":"E","text":"Spasme vasculare prelungite și ischemie"}],"correct":["A","B","C"],"pages":[111],"source":"set-2"},{"id":"set2-Ow5z_N-X","fingerprint":"5873ef94d9283c18","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce definește necroza pulpară complicată (infectată)?","options":[{"id":"A","text":"Mortificarea aseptică a pulpei într-o cameră pulpară închisă."},{"id":"B","text":"Compresia pachetului vasculo-nervos prin traumatisme repetate."},{"id":"C","text":"O stare în care pulpa, deși necrozată, nu determină o inflamație în țesutul periapical."},{"id":"D","text":"Ruperea pachetului vascular pulpar în urma unui traumatism de mare intensitate."},{"id":"E","text":"Mortificarea septică a pulpei dentare sub influența germenilor anaerobi."}],"correct":["E"],"pages":[111],"source":"set-2"},{"id":"set2-EDQR_o2x","fingerprint":"48c260587956be41","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele elemente clinice și paraclinice sunt criterii pentru diagnosticul pozitiv al necrozei pulpare?","options":[{"id":"A","text":"Sensibilitate și sângerare în profunzimea canalului radicular."},{"id":"B","text":"Examenul radiologic arată absența modificărilor parodonțiului apical."},{"id":"C","text":"Modificarea de culoare a dintelui."},{"id":"D","text":"Teste de vitalitate negative."},{"id":"E","text":"Percuția în ax este pozitivă."}],"correct":["B","C","D"],"pages":[112],"source":"set-2"},{"id":"set2-It92T4o9","fingerprint":"f7d7ad3293d10beb","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Cum este definită necroza pulpară complicată?","options":[{"id":"A","text":"O necroză în care camera pulpară este închisă."},{"id":"B","text":"O necroză care se extinde în spațiul periodontal."},{"id":"C","text":"O necroză care afectează parțial țesutul pulpar."},{"id":"D","text":"O necroză care interesează doar spațiul endodontic."},{"id":"E","text":"O necroză de tip colicvație, cu lichefierea țesutului pulpar."}],"correct":["B"],"pages":[112],"source":"set-2"},{"id":"set2-Vi5WOcjG","fingerprint":"42d341218184f245","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce caracteristică diferențiază parodontitele apicale asimptomatice de necroza pulpară în cadrul diagnosticului diferențial?","options":[{"id":"A","text":"Absența sângerării la sondarea canalului."},{"id":"B","text":"Prezența unei radiotransparențe periapicale pe imaginea radiologică."},{"id":"C","text":"Rezultatul negativ la testele de vitalitate."},{"id":"D","text":"Congestia mucoasei vestibulare."},{"id":"E","text":"Modificarea de culoare a coroanei dentare."}],"correct":["B"],"pages":[112],"source":"set-2"},{"id":"set2-byDYl6Jd","fingerprint":"e1ea83b2da32fceb","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Conform Școlii românești de endodonție, care sunt cele trei forme clinice ale parodontitei apicale acute?","options":[{"id":"A","text":"Seroasă, purulentă și abces acut apical."},{"id":"B","text":"Hiperemică, seroasă și purulentă."},{"id":"C","text":"Acută, subacută și cronică."},{"id":"D","text":"Simplă, complicată și totală."},{"id":"E","text":"De colicvație și de coagulare."}],"correct":["B"],"pages":[112],"source":"set-2"},{"id":"set2-Ck0bdLXD","fingerprint":"d68d09e3d302341a","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În cazul parodontitelor apicale asimptomatice, care este localizarea microorganismelor organizate în biofilme?","options":[{"id":"A","text":"Diseminate în circulația sanguină periapicală."},{"id":"B","text":"În cementul radicular și osul alveolar."},{"id":"C","text":"În sistemul endodontic și în canaliculele dentinare."},{"id":"D","text":"Doar în camera pulpară, fără a pătrunde în canalele radiculare."},{"id":"E","text":"În leziunile periapicale, invadând activ apexul."}],"correct":["C"],"pages":[112],"source":"set-2"},{"id":"set2-7p70KS1F","fingerprint":"8b7459ac546c8c45","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Pe ce se bazează în principal diagnosticul de parodontită apicală simptomatică?","options":[{"id":"A","text":"Pe examenul radiologic care evidențiază o lărgire a spațiului periodontal."},{"id":"B","text":"Pe teste de vitalitate pozitive la intensități mari."},{"id":"C","text":"Pe examenul bacteriologic pozitiv din spațiul endodontic."},{"id":"D","text":"Pe semne clinice și simptome precum durerea și sensibilitatea la percuție."},{"id":"E","text":"Pe lipsa sângerării la sondarea canalelor radiculare."}],"correct":["D"],"pages":[112],"source":"set-2"},{"id":"set2-cFSxDKv_","fingerprint":"423057c34c8aa4d0","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce țesuturi sunt afectate de inflamațiile periapicale de cauză endodontică?","options":[{"id":"A","text":"Smaltul și dentina coronară."},{"id":"B","text":"Canaliculele dentinare și sistemul endodontic."},{"id":"C","text":"Osul alveolar, ligamentul periodontal și cementul radicular."},{"id":"D","text":"Doar osul alveolar și mucoasa vestibulară."},{"id":"E","text":"Exclusiv ligamentul periodontal."}],"correct":["C"],"pages":[112],"source":"set-2"},{"id":"set2-NFehiETl","fingerprint":"0653579f9f3721d8","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt semnele obiective ce pot fi identificate la inspecția unui dinte cu necroză pulpară?","options":[{"id":"A","text":"O radiotransparență periapicală vizibilă la inspecție."},{"id":"B","text":"Prezența cariilor profunde care pot deschide camera pulpară."},{"id":"C","text":"Modificări de culoare spre brun sau cenușiu."},{"id":"D","text":"Congestia mucoasei vestibulare."},{"id":"E","text":"Absența oricărei leziuni carioase, dintele fiind indemn."}],"correct":["B","C","E"],"pages":[112],"source":"set-2"},{"id":"set2-U2FX7NR0","fingerprint":"f8f20874562dd9ac","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt cauzele recunoscute ale parodontitei apicale hiperemice?","options":[{"id":"A","text":"Microtraumatismele, cum ar fi cele provocate de aparate ortodontice sau bruxism."},{"id":"B","text":"Agenții microbieni."},{"id":"C","text":"Agenții chimici, precum substanțele medicamentoase iritante aplicate în pungile parodontale."},{"id":"D","text":"Stimulii termici persistenți, cum ar fi lichidele reci sau calde."},{"id":"E","text":"Reacțiile alergice la materialele de obturație de canal."}],"correct":["A","B","C"],"pages":[113],"source":"set-2"},{"id":"set2-LAnGTIWR","fingerprint":"d47df1be8461b1a7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente clinice și radiologice contribuie la diagnosticul pozitiv al parodontitei apicale hiperemice?","options":[{"id":"A","text":"Tumefacție vizibilă a tegumentelor faciale."},{"id":"B","text":"O imagine radiologică cu radiotransparență periapicală bine definită, în cazul unei afecțiuni acute primare."},{"id":"C","text":"Sensibilitate la percuția în ax."},{"id":"D","text":"Prezența simptomatologiei de pulpită totală."},{"id":"E","text":"Congestia mucoasei în dreptul apexului."}],"correct":["C","D","E"],"pages":[113],"source":"set-2"},{"id":"set2-ki-X9zvP","fingerprint":"aeae6cc7e72c11c2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este atitudinea terapeutică recomandată în cazul unei parodontite apicale hiperemice apărute consecutiv unei obturații de canal cu depășire?","options":[{"id":"A","text":"Administrarea de antiinflamatoare și antialgice."},{"id":"B","text":"Intervenție chirurgicală de rezecție apicală imediată."},{"id":"C","text":"Aplicarea de comprese reci pentru a reduce inflamația."},{"id":"D","text":"Prescrierea unui tratament cu antibiotice cu spectru larg."},{"id":"E","text":"Reluarea imediată a tratamentului endodontic."}],"correct":["A"],"pages":[113],"source":"set-2"},{"id":"set2-BuZwCPrW","fingerprint":"ea439e3fe12a6328","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici are durerea în abcesul acut periapical (parodontita apicală acută seroasă)?","options":[{"id":"A","text":"Durerea este descrisă ca fiind pulsatorie și se ameliorează la căldură."},{"id":"B","text":"Durerea se remite complet la administrarea calmantelor uzuale."},{"id":"C","text":"Durerea crește în ritm ascendent, putând evolua de la o jenă la o durere insuportabilă în 24-48 de ore."},{"id":"D","text":"Durerea este exacerbată de creșterea fluxului sangvin în extremitatea cefalică, cum ar fi la aplecarea înainte."},{"id":"E","text":"Durerea este strict localizată la dintele cauzal, fără iradiere."}],"correct":["C","D"],"pages":[113],"source":"set-2"},{"id":"set2--Jv2Rkhr","fingerprint":"ac00e6929e2b473f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În cazul unui abces acut periapical la un canin superior, unde se localizează cel mai frecvent edemul?","options":[{"id":"A","text":"În regiunea submandibulară."},{"id":"B","text":"La nivelul buzei superioare."},{"id":"C","text":"În regiunea geniană."},{"id":"D","text":"La nivelul buzei inferioare și în regiunea mentonieră."},{"id":"E","text":"La nivelul aripii nasului și în regiunea palpebrală."}],"correct":["E"],"pages":[113],"source":"set-2"},{"id":"set2-qdiSG6gO","fingerprint":"6107cc3b3f87a817","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente sunt incluse în diagnosticul pozitiv al abcesului acut periapical?","options":[{"id":"A","text":"Starea generală alterată, cu febră și frisoane."},{"id":"B","text":"Percuția în ax pozitivă."},{"id":"C","text":"Testele de vitalitate pulpară pozitive."},{"id":"D","text":"Caracteristicile specifice ale durerii."},{"id":"E","text":"Absența adenopatiei regionale."}],"correct":["A","B","D"],"pages":[113],"source":"set-2"},{"id":"set2--FMihv8U","fingerprint":"2640aee98632a722","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Conform datelor prezentate, care este evoluția efectelor biologice ale unui sealer endodontic după câteva săptămâni, în absența bacteriilor?","options":[{"id":"A","text":"Sealerul își menține potențialul efect iritant pe termen lung."},{"id":"B","text":"Sealerul se resoarbe complet, fiind înlocuit de țesut osos."},{"id":"C","text":"Reacția de priză a materialului este completă și acesta devine aparent fără efecte biologice."},{"id":"D","text":"Materialul induce o reacție inflamatorie cronică redusă."},{"id":"E","text":"Reacția inflamatorie se intensifică, indiferent de prezența bacteriilor."}],"correct":["C"],"pages":[113],"source":"set-2"},{"id":"set2-_yIQAL6J","fingerprint":"e0bcd30a79cb857e","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care dintre următoarele afecțiuni sunt incluse în diagnosticul diferențial al unui abces apical acut?","options":[{"id":"A","text":"Nevralgia de trigemen, caracterizată prin durere în crize ce persistă după tratamentul odontologic corect."},{"id":"B","text":"Foliculita dinților incluși."},{"id":"C","text":"Parodontita marginală cronică, caracterizată prin pierderea atașamentului gingival și resorbție osoasă orizontală."},{"id":"D","text":"Abcesul parodontal marginal, caracterizat prin teste de vitalitate pozitive la dintele cauzal."},{"id":"E","text":"Pulpita acută."}],"correct":["E"],"pages":[114],"source":"set-2"},{"id":"set2--SIwNuGi","fingerprint":"555ad348989925b0","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este o cauză frecventă a abcesului apical acut și ce aspect radiologic poate prezenta în cazul în care nu este o acutizare a unei leziuni cronice?","options":[{"id":"A","text":"Este o complicație a parodontitei apicale cronice și prezintă mereu o radiotransparență bine conturată."},{"id":"B","text":"Apare doar la dinți vitali și nu poate fi detectat prin nicio metodă radiologică."},{"id":"C","text":"Rezultă dintr-un traumatism direct și prezintă întotdeauna o radiotransparență difuză periapicală."},{"id":"D","text":"Este cauzat de microorganismele din canalul radicular și poate fi neînsoțit de semne radiologice evidente."},{"id":"E","text":"Este declanșat de iritanți chimici și se manifestă radiologic printr-o zonă de osteoscleroză periapicală."}],"correct":["D"],"pages":[114],"source":"set-2"},{"id":"set2-DNbp1uAH","fingerprint":"dc481a29697313f8","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În cazul unui abces apical acut localizat la un molar mandibular, care este mecanismul de apariție a trismusului?","options":[{"id":"A","text":"Extinderea procesului infecțios la articulația temporo-mandibulară."},{"id":"B","text":"Compresia nervului alveolar inferior de către edemul inflamator."},{"id":"C","text":"Răspunsul reflex la durerea intensă de la nivelul dintelui cauzal."},{"id":"D","text":"Blocarea mecanică a deschiderii gurii de către tumefacția masivă a planșeului bucal."},{"id":"E","text":"Interesarea inflamatorie a mușchilor ridicători ai mandibulei."}],"correct":["E"],"pages":[114],"source":"set-2"},{"id":"set2-MWTtm_KZ","fingerprint":"8306c1239bd2f1a4","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce reprezintă celulita în contextul evoluției unui abces cu punct de plecare dentar?","options":[{"id":"A","text":"O reacție alergică la produsele microbiene din canalul radicular."},{"id":"B","text":"Colectarea puroiului strict în spațiul submucos."},{"id":"C","text":"Difuzarea infecției în țesuturile faciale de vecinătate."},{"id":"D","text":"O tumefacție bine conturată și fluctuantă la palpare."},{"id":"E","text":"Faza endoosoasă a abcesului apical acut."}],"correct":["C"],"pages":[114],"source":"set-2"},{"id":"set2-QNp_uwAu","fingerprint":"364d45530f4d1939","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele semne clinice sunt caracteristice pentru primul stadiu evolutiv al unui abces apical acut?","options":[{"id":"A","text":"Starea generală a pacientului este alterată, cu polipnee și hipotensiune."},{"id":"B","text":"Semnul godeului nu este prezent în această fază."},{"id":"C","text":"Hipertermia poate fi prezentă."},{"id":"D","text":"Tegumentele deasupra tumefacției sunt calde, destinse și ușor roșietice."},{"id":"E","text":"Tumefacția este bine delimitată și fluctuantă la palpare."}],"correct":["B","C","D"],"pages":[114],"source":"set-2"},{"id":"set2-bMOYK1UU","fingerprint":"81368f31af953da7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Cum se modifică caracterul durerii în abcesul apical acut în funcție de localizarea procesului infecțios?","options":[{"id":"A","text":"Durerea este localizată în stadiul endoosos și iradiată în stadiul superiostal."},{"id":"B","text":"Durerea are un caracter pulsatil în stadiul endoosos și devine continuă în stadiul superiostal."},{"id":"C","text":"Durerea este absentă în stadiul endoosos și apare doar în stadiul superiostal."},{"id":"D","text":"Durerea este exacerbată de căldură în stadiul endoosos și de frig în stadiul superiostal."},{"id":"E","text":"Durerea este iradiată în stadiul endoosos și devine localizată în stadiul superiostal."}],"correct":["E"],"pages":[114],"source":"set-2"},{"id":"set2-PhpNHw_W","fingerprint":"7d54c9d9bd1a68ce","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce manifestări clinice caracterizează faza supurativă a unui abces apical acut netratat?","options":[{"id":"A","text":"Tumefacția devine bine delimitată și este fluctuantă la palpare."},{"id":"B","text":"Semnul godeului, absent în prima fază, devine prezent."},{"id":"C","text":"Tumefacția facială scade, în timp ce mobilitatea dintelui crește."},{"id":"D","text":"Tegumentele devin palide și reci la atingere."},{"id":"E","text":"Starea generală a pacientului este alterată, putând include paloare, polipnee și hipotensiune."}],"correct":["A","B","E"],"pages":[114],"source":"set-2"},{"id":"set2-muFfW9_F","fingerprint":"918de6482c65e0ab","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele descrieri ale durerii sunt specifice unui abces apical acut?","options":[{"id":"A","text":"Se ameliorează semnificativ în timpul nopții."},{"id":"B","text":"Pacientul descrie o senzație de dinte elongat."},{"id":"C","text":"Este intensă la cea mai mică atingere a dintelui."},{"id":"D","text":"Are un caracter pulsatil în stadiul purulent."},{"id":"E","text":"Este o durere surdă, de intensitate redusă, care nu iradiază."}],"correct":["B","C","D"],"pages":[114],"source":"set-2"},{"id":"set2-zCi3XHOz","fingerprint":"0fe9e761688bdf6c","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este prioritatea terapeutică în gestionarea unei urgențe endodontice caracterizate prin prezența unui exudat purulent?","options":[{"id":"A","text":"Realizarea obturației de canal definitive în aceeași ședință."},{"id":"B","text":"Evacuarea exudatului purulent."},{"id":"C","text":"Administrarea imediată de antibiotice cu spectru larg."},{"id":"D","text":"Stabilirea unui plan de tratament chirurgical."},{"id":"E","text":"Efectuarea testelor de vitalitate pentru confirmarea diagnosticului."}],"correct":["B"],"pages":[115],"source":"set-2"},{"id":"set2-32CwdFCa","fingerprint":"a05369ff515b358e","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce modificări simptomatologice apar atunci când un proces supurativ fistulizează?","options":[{"id":"A","text":"Durerea scade în intensitate."},{"id":"B","text":"Apare o leucitoză accentuată."},{"id":"C","text":"Tumefacția se diminuează."},{"id":"D","text":"Febra se reduce."},{"id":"E","text":"Testele de vitalitate devin pozitive."}],"correct":["A","C","D"],"pages":[115],"source":"set-2"},{"id":"set2-d3zrpC74","fingerprint":"b3248989eae6b705","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este aspectul radiologic tipic într-o infecție apicală acută cu evoluție rapidă?","options":[{"id":"A","text":"Prezența unei resorbții radiculare externe la nivelul apexului."},{"id":"B","text":"O zonă apicală cu aspect normal sau cu o lărgire discretă a spațiului periodontal."},{"id":"C","text":"Imagine de osteoscleroză periapicală difuză."},{"id":"D","text":"O zonă de radiotransparență periapicală extinsă și bine delimitată."},{"id":"E","text":"Fractură radiculară verticală vizibilă."}],"correct":["B"],"pages":[115],"source":"set-2"},{"id":"set2-QsDSOhjZ","fingerprint":"5aea9db653b34910","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente sunt utilizate pentru stabilirea diagnosticului pozitiv al unui abces apical acut?","options":[{"id":"A","text":"Prezența unei fistule active."},{"id":"B","text":"Caracterele specifice ale durerii."},{"id":"C","text":"Răspunsul negativ la testele de vitalitate."},{"id":"D","text":"Prezența tumefacției."},{"id":"E","text":"Răspuns pozitiv la testele de vitalitate."}],"correct":["B","C","D"],"pages":[115],"source":"set-2"},{"id":"set2-ryFD7c2o","fingerprint":"b121c276cc1f2fc2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În ce situație specifică, în cadrul tratamentului de urgență, se indică lăsarea dintelui deschis pentru o perioadă de 24-48 de ore?","options":[{"id":"A","text":"Când pacientul prezintă o alergie la penicilină."},{"id":"B","text":"Ori de câte ori drenajul endodontic este posibil."},{"id":"C","text":"Când simptomatologia este foarte intensă și uscarea canalului nu poate fi obținută."},{"id":"D","text":"Imediat după realizarea unei incizii pentru drenaj chirurgical."},{"id":"E","text":"După aplicarea unui pansament cu hidroxid de calciu."}],"correct":["C"],"pages":[115],"source":"set-2"},{"id":"set2-Rn9bnrjm","fingerprint":"6bec1624273582e3","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce scheme de tratament antibiotic sunt indicate pentru o infecție endodontică severă la un pacient fără alergie la penicilină?","options":[{"id":"A","text":"Amoxicilină și acid clavulanic 1000-2000 mg/zi."},{"id":"B","text":"Amoxicilină 2g/zi asociată cu metronidazol 1,5g/zi."},{"id":"C","text":"Doar antialgice."},{"id":"D","text":"Metronidazol 1,5g/zi în monoterapie."},{"id":"E","text":"Clindamicină 1,2 g/zi."}],"correct":["A","B"],"pages":[115],"source":"set-2"},{"id":"set2-Au7B_izJ","fingerprint":"d36d04fe2aae71b5","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce manoperă este recomandată atunci când, după crearea accesului endodontic, drenajul puroiului nu se produce spontan?","options":[{"id":"A","text":"Se pătrunde 1 mm dincolo de foramenul apical cu un ac de diametru mic."},{"id":"B","text":"Se recurge imediat la drenajul chirurgical prin incizie."},{"id":"C","text":"Se aplică o pastă de hidroxid de calciu și o obturație temporară."},{"id":"D","text":"Se lasă dintele deschis pentru 24-48 de ore fără a forța drenajul."},{"id":"E","text":"Se irigă canalul cu hipoclorit de sodiu și se așteaptă 30 de minute."}],"correct":["A"],"pages":[115],"source":"set-2"},{"id":"set2-EL44iz70","fingerprint":"7664bb4aae5a69cf","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt etapele procedurii de drenaj endodontic asistat, realizate după un interval de aproximativ 30 de minute de la evacuarea inițială a exudatului?","options":[{"id":"A","text":"Aplicarea unui pansament cu hidroxid de calciu și închiderea etanșă."},{"id":"B","text":"Lăsarea dintelui deschis pentru 48 de ore."},{"id":"C","text":"Permeabilizarea apexului și administrarea de antibiotice."},{"id":"D","text":"Izolarea cu digă și lavaje cu NaOCl."},{"id":"E","text":"Debridarea și instrumentarea canalului radicular."}],"correct":["A","E"],"pages":[115],"source":"set-2"},{"id":"set2-V0ZGpuKT","fingerprint":"58065063d655cdc8","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"În ce situații este contraindicată închiderea cavității de acces după efectuarea unui drenaj endodontic?","options":[{"id":"A","text":"Se constată prezența unui exudat în cantitate mare la nivelul canalelor radiculare."},{"id":"B","text":"Pacientul acuză o sensibilitate dureroasă marcată."},{"id":"C","text":"La inspecție se observă prezența unei fistule active."},{"id":"D","text":"Medicul dispune de timp insuficient pentru procedură."},{"id":"E","text":"Starea generală a pacientului este alterată, cu prezența unei tumefacții difuze."}],"correct":["A","B","D","E"],"pages":[116],"source":"set-2"},{"id":"set2-wF_qYsW9","fingerprint":"96ac0c9b187e0d36","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afecțiuni sunt clasificate ca forme de parodontită apicală asimptomatică (cronică)?","options":[{"id":"A","text":"Necroza complicată."},{"id":"B","text":"Granulomul periapical."},{"id":"C","text":"Pulpita cronică."},{"id":"D","text":"Abcesul cronic apical."},{"id":"E","text":"Parodontita apicală cu hipercementoză."}],"correct":["B","D","E"],"pages":[116],"source":"set-2"},{"id":"set2-FXK5ThtQ","fingerprint":"e29193315622f423","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente anamnestice sunt sugestive pentru o parodontită apicală asimptomatică?","options":[{"id":"A","text":"Durere continuă, de intensitate mare, cu caracter nevralgiform."},{"id":"B","text":"Ușoara senzație de egresiune."},{"id":"C","text":"Unul sau mai multe pusee acute în antecedente."},{"id":"D","text":"Absența completă a oricărui simptom dureros în istoricul dintelui."},{"id":"E","text":"O senzație de presiune constantă, fără istoric de durere."}],"correct":["B","C"],"pages":[116],"source":"set-2"},{"id":"set2-SdqUB_v2","fingerprint":"5b0cc7e288282872","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care este aspectul radiologic caracteristic al parodontitei apicale cronice fibroase?","options":[{"id":"A","text":"Imagine radioopacă la nivelul apexului, sugestivă pentru hipercementoză."},{"id":"B","text":"O radiotransparență periapicală bine delimitată, cu aspect de „calotă”."},{"id":"C","text":"Aspect structural osos parțial păstrat în interiorul radiotransparenței."},{"id":"D","text":"O zonă de radiotransparență ce înconjoară apexul, cu un contur rotund-ovalar."},{"id":"E","text":"O radiotransparență difuză, neconturată, însoțită de resorbție radiculară externă."}],"correct":["B","C"],"pages":[116],"source":"set-2"},{"id":"set2-4a5NH7ts","fingerprint":"fda572a81d8d2556","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce afirmație descrie corect structura și formarea granulomului periapical?","options":[{"id":"A","text":"Factorul etiologic principal este reprezentat de substanțe chimice iritante și suprainstrumentare."},{"id":"B","text":"Este format din țesut de granulație la apex, înconjurat de o capsulă de fibre de colagen."},{"id":"C","text":"Resorbția osoasă este un proces pasiv, determinat de presiunea exercitată de leziune."},{"id":"D","text":"Diagnosticul de certitudine între granulom și chistul periapical se poate stabili doar radiologic."},{"id":"E","text":"Bacteriile reprezintă factorul etiologic în formarea sa."}],"correct":["B","E"],"pages":[116],"source":"set-2"},{"id":"set2-AtObKupB","fingerprint":"d3ffa5dc81c90131","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt factorii etiologici implicați în dezvoltarea granulomului periapical?","options":[{"id":"A","text":"Supracontactele ocluzale pe restaurări recente."},{"id":"B","text":"Toxinele bacteriene, precum exo- și endotoxinele."},{"id":"C","text":"Bacteriile localizate la nivelul țesutului pulpar necrozat."},{"id":"D","text":"Suprainstrumentarea canalelor radiculare."},{"id":"E","text":"Obturațiile de canal neetanșe."}],"correct":["B","C","D"],"pages":[116],"source":"set-2"},{"id":"set2-Ne82paBi","fingerprint":"516fe72dd1c679e0","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Prin ce metodă se poate stabili cu certitudine diagnosticul diferențial între diversele forme granulomatoase ale parodontitelor apicale cronice?","options":[{"id":"A","text":"Prin teste de vitalitate pulpară."},{"id":"B","text":"Pe baza simptomatologiei acuzate de pacient."},{"id":"C","text":"Prin examen radiologic bi- sau tridimensional."},{"id":"D","text":"Prin analiza prezenței sau absenței unei fistule."},{"id":"E","text":"Prin examen morfopatologic."}],"correct":["E"],"pages":[116],"source":"set-2"},{"id":"set2-1iC37bYo","fingerprint":"eaf2cb1567bcdd7f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următorii factori pot determina o inflamație cu evoluție lentă, caracteristică parodontitelor apicale asimptomatice?","options":[{"id":"A","text":"Ocluzia traumatică acută."},{"id":"B","text":"Prezența corpilor străini precum conuri de hârtie."},{"id":"C","text":"Suprainstrumentarea canalului radicular."},{"id":"D","text":"Resturi alimentare impactate în camera pulpară."},{"id":"E","text":"Fibre de bumbac"}],"correct":["B","C","E"],"pages":[117],"source":"set-2"},{"id":"set2-z30yIRk4","fingerprint":"06d814f95ad623cc","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care sunt principalele tipuri de celule inflamatorii prezente în țesutul de granulație al unei parodontite apicale asimptomatice (granulomatoase)?","options":[{"id":"A","text":"Macrofage și limfocite."},{"id":"B","text":"Neutrofile și eozinofile."},{"id":"C","text":"Plasmocite și mastocite."},{"id":"D","text":"Osteoclaste și osteoblaste."},{"id":"E","text":"Cementoclaste și dentinoclaste."}],"correct":["A"],"pages":[117],"source":"set-2"},{"id":"set2-OR9SGhaJ","fingerprint":"441b847102463a76","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce element histologic delimitează leziunea în parodontita apicală granulomatoasă, atașându-se de suprafața radiculară?","options":[{"id":"A","text":"Un infiltrat inflamator difuz fără delimitare."},{"id":"B","text":"O barieră de osteoblaste active."},{"id":"C","text":"O zonă de necroză de lichefacție."},{"id":"D","text":"Un perete epitelial pluristratificat pavimentos."},{"id":"E","text":"O capsulă fibroasă formată din fibre de colagen."}],"correct":["E"],"pages":[117],"source":"set-2"},{"id":"set2-0gsvmXfk","fingerprint":"9ae0c8e378bd7f91","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În contextul diagnosticului diferențial radiologic al unei leziuni periapicale, ce structură anatomică se caracterizează printr-o imagine perfect rotundă în zona premolarilor inferiori, care poate fi decalată de dinte la schimbarea incidenței radiografiei?","options":[{"id":"A","text":"Gaura mentonieră."},{"id":"B","text":"Un granulom periapical."},{"id":"C","text":"Fosele nazale."},{"id":"D","text":"Sinusul maxilar."},{"id":"E","text":"Gaura incisivă."}],"correct":["A"],"pages":[117],"source":"set-2"},{"id":"set2-R72t5vDU","fingerprint":"476a084b9cc09599","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații sunt adevărate cu privire la chistul periradicular?","options":[{"id":"A","text":"Reprezintă stadiul final al unui granulom epitelial netratat."},{"id":"B","text":"În fazele incipiente, la palpare se constată întotdeauna o consistență osoasă crescută."},{"id":"C","text":"Comunică întotdeauna cu lumenul canalului radicular."},{"id":"D","text":"Testele de vitalitate pulpară sunt negative pentru dintele implicat."},{"id":"E","text":"Este o cavitate căptușită cu epiteliu pluristratificat pavimentos."}],"correct":["A","D","E"],"pages":[117],"source":"set-2"},{"id":"set2-yVhlxzLA","fingerprint":"749abde857686d56","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce tip de resorbție tisulară este caracteristică fazei asimptomatice a parodontitei apicale granulomatoase?","options":[{"id":"A","text":"Resorbție a osului alveolar de către cementoclaste."},{"id":"B","text":"Absența oricărui tip de resorbție tisulară."},{"id":"C","text":"Resorbție rapidă a apexului radicular de către cementoclaste."},{"id":"D","text":"Resorbție lentă a țesutului osos periapical de către osteoclaste."},{"id":"E","text":"Resorbția exclusivă a cementului radicular."}],"correct":["D"],"pages":[117],"source":"set-2"},{"id":"set2-iJNQ5zNX","fingerprint":"86d7927418e02b74","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Conform clasificării prezentate, care sunt cele două tipuri de chisturi periapicale?","options":[{"id":"A","text":"Chisturi periapicale adevărate și chisturi periapicale în buzunar."},{"id":"B","text":"Chisturi simple și chisturi complexe."},{"id":"C","text":"Chisturi inflamatorii și chisturi de dezvoltare."},{"id":"D","text":"Chisturi epiteliale și chisturi conjunctive."},{"id":"E","text":"Chisturi acute și chisturi cronice."}],"correct":["A"],"pages":[117],"source":"set-2"},{"id":"set2-4Lx-x12i","fingerprint":"c88f4de8c54414be","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce semn clinic poate fi observat la palpare în fazele avansate ale unui chist periradicular?","options":[{"id":"A","text":"Retracție gingivală accentuată la nivelul dintelui cauzal."},{"id":"B","text":"O consistență dură, nedeformabilă a osului."},{"id":"C","text":"Sensibilitate crescută la atingerea mucoasei."},{"id":"D","text":"O temperatură locală crescută."},{"id":"E","text":"Consistență redusă și crepitație a osului alveolar."}],"correct":["E"],"pages":[117],"source":"set-2"},{"id":"set2-kVO0L-5K","fingerprint":"e63f3a0d5e553d14","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce complicații pot apărea în evoluția unui chist periradicular voluminos netratat?","options":[{"id":"A","text":"Suprainfectarea."},{"id":"B","text":"Fractura spontană a osului."},{"id":"C","text":"Vindecarea spontană prin scleroză osoasă."},{"id":"D","text":"Bombarea mucoasei."},{"id":"E","text":"Transformarea într-un granulom periapical."}],"correct":["A","B"],"pages":[117],"source":"set-2"},{"id":"set2-sk08qteJ","fingerprint":"920ec69aba236082","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care sunt criteriile de stabilire a diagnosticului pozitiv pentru o afecțiune periapicală de natură endodontică ce necesită tratament conservativ?","options":[{"id":"A","text":"Exclusiv pe baza simptomatologiei dureroase acute raportate de pacient."},{"id":"B","text":"Prin identificarea unei fistule la nivelul mucoasei alveolare."},{"id":"C","text":"Prin efectuarea unui diagnostic diferențial cu alte forme chistice."},{"id":"D","text":"Doar prin examen radiologic, testele de vitalitate fiind irelevante."},{"id":"E","text":"Pe baza examenului radiologic, a testelor de vitalitate și a simptomatologiei."}],"correct":["E"],"pages":[118],"source":"set-2"},{"id":"set2-hOBRCPLG","fingerprint":"b1b0c236f7f23e0f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În ce situație este indicată aplicarea unei medicații intracanalare cu hidroxid de calciu în timpul tratamentului endodontic conservativ al unei leziuni chistice?","options":[{"id":"A","text":"Atunci când imaginea radiologică a leziunii nu se reduce în dimensiune după 6 luni."},{"id":"B","text":"În prezența unui biofilm extraradicular, pentru a facilita vindecarea."},{"id":"C","text":"Ca o procedură standard, în toate cazurile, după irigarea canalului radicular."},{"id":"D","text":"Când pacientul prezintă o simptomatologie clinică dureroasă persistentă."},{"id":"E","text":"Dacă după realizarea tratamentului mecanic și a irigării nu se poate obține uscarea canalului."}],"correct":["E"],"pages":[118],"source":"set-2"},{"id":"set2-lGKZsTSA","fingerprint":"27a5b7e7591313da","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt indicațiile pentru un tratament chirurgical după finalizarea unui tratament endodontic conservativ?","options":[{"id":"A","text":"Imposibilitatea de a obține uscarea canalului în timpul tratamentului mecanic."},{"id":"B","text":"Prezența unui biofilm extraradicular, periapical, în ciuda tratamentului corect instituit."},{"id":"C","text":"Dintele cauzal este devital și prezintă semne de necroză pulpară."},{"id":"D","text":"Imaginea radiologică nu se reduce ca dimensiune, nearătând o evoluție spre vindecare."},{"id":"E","text":"Apariția unei simptomatologii clinice."}],"correct":["B","D","E"],"pages":[118],"source":"set-2"},{"id":"set2-_8El1Svd","fingerprint":"a4bf4f153a33b1d1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici definitorii prezintă parodontita apicală condensantă?","options":[{"id":"A","text":"Radiografic se observă un os periapical cu aspect de hipermineralizare și îngustarea spațiului periodontal."},{"id":"B","text":"Trăsătura esențială este lărgirea spațiului periapical."},{"id":"C","text":"Este o afecțiune a țesuturilor parodontale apicale ce are ca trăsătură esențială îngustarea spațiului periapical."},{"id":"D","text":"Prezența unei fistule prin care se evacuează puroi este un semn patognomonic."},{"id":"E","text":"Simptomatologia este săracă sau absentă, iar dintele este devital."}],"correct":["A","C","E"],"pages":[118],"source":"set-2"},{"id":"set2-bSKZWqCA","fingerprint":"9fb5de004b3573bd","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce reprezintă fistula în contextul unui abces apical cronic?","options":[{"id":"A","text":"Un traiect de la abces la suprafața mucozală sau tegument, prin care se evacuează puroi."},{"id":"B","text":"O leziune inflamatorie cronică localizată la nivelul țesuturilor periapicale."},{"id":"C","text":"O reacție de hipermineralizare a osului periapical ca răspuns la o infecție cronică."},{"id":"D","text":"O cale de pătrundere a bacteriilor către zona periapicală."},{"id":"E","text":"Un defect de atașament larg, similar unei pungi parodontale."}],"correct":["A"],"pages":[118],"source":"set-2"},{"id":"set2-xw26xLT-","fingerprint":"1928962bd9595ee1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt avantajele prezenței unei fistule în cazul unui abces apical cronic?","options":[{"id":"A","text":"Previne exacerbarea parodontitei apicale prin menținerea unei presiuni constante."},{"id":"B","text":"Contribuie la diagnosticarea sursei infecției prin utilizarea unui con de gutapercă."},{"id":"C","text":"Asigură epitelizarea completă și permanentă a traiectului, prevenind recidivele."},{"id":"D","text":"Favorizează reducerea durerii prin eliminarea exsudatului."},{"id":"E","text":"Stimulează un răspuns imun local care duce la vindecarea spontană a leziunii."}],"correct":["B","D"],"pages":[118],"source":"set-2"},{"id":"set2-y_GP8U_A","fingerprint":"7c5115e9f26eb2c1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În ce situație clinică a unui abces apical cronic este necesar un diagnostic diferențial cu o leziune parodontală, o fisură sau o fractură radiculară?","options":[{"id":"A","text":"Când pacientul acuză o tumefiere redusă și durere ușoară la atingerea dintelui."},{"id":"B","text":"Când fistula se deschide la nivelul tegumentelor feței."},{"id":"C","text":"Când orificiul fistulos se epitelizează temporar între episoadele de drenaj."},{"id":"D","text":"Când fistula se deschide la nivelul furcației unui dinte pluriradicular."},{"id":"E","text":"Când fistula se deschide în șanțul crevicular și se constată un defect de atașament strâmt."}],"correct":["E"],"pages":[118],"source":"set-2"},{"id":"set2-AAEoLEkc","fingerprint":"23b943bd649ceec4","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce simptomatologie poate apărea în cazul închiderii fistulei unui abces apical cronic?","options":[{"id":"A","text":"Formarea unui nou traiect fistulos către tegument."},{"id":"B","text":"O durere acută, pulsatile, similară unui abces apical acut."},{"id":"C","text":"Dispariția completă a oricărui semn sau simptom clinic."},{"id":"D","text":"O tumefiere redusă a zonei și durere ușoară la atingerea dintelui și la palpare."},{"id":"E","text":"Îngustarea spațiului periodontal vizibilă pe radiografie."}],"correct":["D"],"pages":[118],"source":"set-2"},{"id":"set2-wkUTdwW5","fingerprint":"805ec92f0528f1ea","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații caracterizează parodontita apicală cronică acutizată?","options":[{"id":"A","text":"Diagnosticul pozitiv se bazează exclusiv pe prezența unei fistule."},{"id":"B","text":"Se manifestă prin simptomatologia unui abces alveolar acut la un dinte cu o radiotransparență apicală preexistentă."},{"id":"C","text":"Tratamentul constă exclusiv în drenaj chirurgical, fără abordarea canalului radicular."},{"id":"D","text":"Acutizarea se datorează întotdeauna unei iritații mecanice prin suprainstrumentare."},{"id":"E","text":"Este cunoscută și sub denumirea de „abces Phoenix”."}],"correct":["B","E"],"pages":[119],"source":"set-2"},{"id":"set2-pidbAf4z","fingerprint":"c2fd78028f16c58f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce mecanism este direct responsabil pentru apariția simptomatologiei acute în parodontita apicală cronică acutizată?","options":[{"id":"A","text":"Invazia directă a bacteriilor în circulația sanguină sistemică."},{"id":"B","text":"Reactivarea virusului Zoster la nivelul apexului dentar."},{"id":"C","text":"Presiunea crescută a exsudatului purulent care nu poate fistuliza."},{"id":"D","text":"Eliberarea unei cantități mari de endotoxine bacteriene."},{"id":"E","text":"O reacție alergică la materialele de obturație de canal."}],"correct":["D"],"pages":[119],"source":"set-2"},{"id":"set2-InreVcyn","fingerprint":"0675d6fc7c26bf00","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este considerat cel mai stabil și caracteristic semn radiologic inițial al inflamației periapicale?","options":[{"id":"A","text":"Lărgirea spațiului periodontal."},{"id":"B","text":"Absența oricăror modificări radiologice."},{"id":"C","text":"Resorbția externă a apexului radicular."},{"id":"D","text":"O zonă de osteoscleroză difuză în jurul rădăcinii."},{"id":"E","text":"Prezența unei radiotransparențe periapicale rotunde, bine delimitate."}],"correct":["A"],"pages":[119],"source":"set-2"},{"id":"set2-baKPzdq9","fingerprint":"b20680a6b880ac9f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Cu privire la interpretarea radiologică a patologiei periapicale, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Diferențierea certă între un granulom și un chist periapical se poate face pe baza examenului radiologic uzual."},{"id":"B","text":"Dimensiunea radiotransparenței observate pe o radiografie retroalveolară este mai mică decât leziunea osoasă reală."},{"id":"C","text":"O leziune osoasă periapicală devine de obicei vizibilă radiologic după aproximativ 3-4 săptămâni de la debut."},{"id":"D","text":"Parodontitele apicale simptomatice se caracterizează întotdeauna printr-o radiotransparență extinsă."},{"id":"E","text":"Radiotransparența periapicală este un semn patognomonic, indicând cu certitudine o parodontită apicală."}],"correct":["B","C"],"pages":[119],"source":"set-2"},{"id":"set2-nBotC_S5","fingerprint":"13a27b4265403efb","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În cazul unui pacient care prezintă o fistulă la nivelul mucoasei orale, cu ce afecțiuni non-odontogene trebuie realizat diagnosticul diferențial?","options":[{"id":"A","text":"Osteomielită, tuberculoză și actinomicoză."},{"id":"B","text":"Procese maligne, patologie nevralgiformă și durere psihogenă."},{"id":"C","text":"Patologie parodontală marginală și sindrom endo-periodontal."},{"id":"D","text":"Pulpită ireversibilă și abces Phoenix."},{"id":"E","text":"Chisturi de dezvoltare și tumori benigne ale maxilarelor."}],"correct":["A"],"pages":[119],"source":"set-2"},{"id":"set2-P3y55jf1","fingerprint":"0b09fb90943814ef","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este metoda principală recomandată pentru diferențierea leziunilor periapicale granulomatoase de alte forme de patologie periapicală?","options":[{"id":"A","text":"Prezența simptomatologiei dureroase la percuție."},{"id":"B","text":"Examenul morfopatologic sau biopsia."},{"id":"C","text":"Examenul radiologic uzual, care arată o imagine specifică."},{"id":"D","text":"Poziționarea radiotransparenței în raport cu apexul dentar."},{"id":"E","text":"Răspunsul la tratamentul endodontic."}],"correct":["B"],"pages":[119],"source":"set-2"},{"id":"set2-A7HFEFba","fingerprint":"051ce5a568fbaa8d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt motivele pentru care o leziune osoasă periapicală ar putea să nu fie detectabilă pe o radiografie retroalveolară, chiar dacă este prezentă?","options":[{"id":"A","text":"Imaginea leziunii este mascată de suprapunerea rădăcinilor."},{"id":"B","text":"Pacientul nu prezintă simptome clinice."},{"id":"C","text":"Leziunea este de dimensiuni prea mici."},{"id":"D","text":"Leziunea este localizată pe versantul lingual sau vestibular al rădăcinii."},{"id":"E","text":"Inflamația este limitată strict la ligamentul parodontal, fără afectare osoasă."}],"correct":["A","C","D"],"pages":[120],"source":"set-2"},{"id":"set2-okxKeHli","fingerprint":"c88982b17349df98","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce reprezintă o infecție endodontică primară?","options":[{"id":"A","text":"O infecție cauzată exclusiv de Enterococcus faecalis."},{"id":"B","text":"O infecție cauzată de microorganisme care invadează și colonizează pentru prima dată țesutul pulpar necrotic."},{"id":"C","text":"O infecție care apare după finalizarea tratamentului endodontic."},{"id":"D","text":"O infecție în care se găsesc în medie 5 specii bacteriene."},{"id":"E","text":"O infecție care pătrunde în spațiul endodontic prin fenomenul de anacoreză."}],"correct":["B"],"pages":[120],"source":"set-2"},{"id":"set2-iE-J0sdp","fingerprint":"13b7297012884e97","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la infecția endodontică secundară sunt corecte?","options":[{"id":"A","text":"Enterococcus faecalis și Candida sunt specii frecvent întâlnite în acest tip de infecție."},{"id":"B","text":"Apare doar ca urmare a restaurărilor coronare defectuoase."},{"id":"C","text":"Este cauzată de microorganisme care nu au fost prezente în timpul infecției primare."},{"id":"D","text":"Poate apărea între două ședințe de tratament endodontic."},{"id":"E","text":"Poate deveni persistentă și poate determina eșecul tratamentului endodontic."}],"correct":["A","C","D","E"],"pages":[120],"source":"set-2"},{"id":"set2-Trvg87T4","fingerprint":"6d51785e37678e24","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce factori contribuie la capacitatea de supraviețuire a Enterococcus faecalis în sistemul de canale radiculare, fiind astfel incriminat în eșecul tratamentului endodontic?","options":[{"id":"A","text":"Dimensiunile sale mari, care blochează acțiunea instrumentelor endodontice."},{"id":"B","text":"Dimensiunile sale reduse, care îi permit să pătrundă în profunzimea tubulilor dentinari."},{"id":"C","text":"Abilitatea de a se organiza sub forma unui biofilm dens pe pereții canalului."},{"id":"D","text":"Rezistența sa la acțiunea hidroxidului de calciu."},{"id":"E","text":"Capacitatea sa de a supraviețui în condiții de privare de nutrienți."}],"correct":["B","C","D","E"],"pages":[120],"source":"set-2"},{"id":"set2--W4HE57I","fingerprint":"e071a3fae3882ab4","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Prin care dintre următoarele căi pot pătrunde bacteriile în spațiul endodontic?","options":[{"id":"A","text":"Exclusiv prin fracturi coronare vizibile clinic."},{"id":"B","text":"Prin fenomenul de anacoreză, din circulația sanguină."},{"id":"C","text":"Prin leziuni parodontale."},{"id":"D","text":"În urma procedurilor de detartraj și planare radiculară."},{"id":"E","text":"Prin procese carioase."}],"correct":["B","C","D","E"],"pages":[120],"source":"set-2"},{"id":"set2-ykVHeUX2","fingerprint":"572ecd24a9ca83bd","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În ce situație modificările radiologice pot fi absente, în ciuda prezenței simptomelor clinice de parodontită apicală?","options":[{"id":"A","text":"Când inflamația interesează doar ligamentul parodontal."},{"id":"B","text":"În cazul unei infecții endodontice primare."},{"id":"C","text":"Întotdeauna după finalizarea tratamentului endodontic."},{"id":"D","text":"Când leziunea osoasă este foarte extinsă."},{"id":"E","text":"Când există canale laterale multiple."}],"correct":["A"],"pages":[120],"source":"set-2"},{"id":"set2-jMwl2vCk","fingerprint":"73863044f5e5b6be","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt unele dintre mecanismele care explică capacitatea de supraviețuire a Enterococcus faecalis în eșecul tratamentului endodontic?","options":[{"id":"A","text":"Adaptarea la condiții nefavorabile prin reglarea expresiei genice."},{"id":"B","text":"Dependența sa strictă de nutrienții furnizați de alte bacterii din biofilm."},{"id":"C","text":"Abilitatea de a coloniza pereții canalului radicular și de a se organiza într-un biofilm dens."},{"id":"D","text":"Rezistența sa în fața acțiunii hidroxidului de calciu."},{"id":"E","text":"Penetrarea în profunzimea tubulilor dentinari datorită dimensiunilor sale reduse."}],"correct":["A","C","D","E"],"pages":[121],"source":"set-2"},{"id":"set2-aBKtVT8G","fingerprint":"6ebf1116469a3cdc","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce microorganisme sunt frecvent izolate în cazul unei infecții extraradiculare?","options":[{"id":"A","text":"Specii de Actinomyces"},{"id":"B","text":"Enterococcus faecalis"},{"id":"C","text":"Leucocite neutrofile polimorfonucleare"},{"id":"D","text":"Candida albicans"},{"id":"E","text":"Specii de Propionibacterium"}],"correct":["A","D","E"],"pages":[121],"source":"set-2"},{"id":"set2-98qFiVa6","fingerprint":"5f7e4a872b94ee8f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În cadrul inflamației periapicale, care este prima categorie de celule care extravazează și migrează spre zona afectată?","options":[{"id":"A","text":"Limfocitele"},{"id":"B","text":"Macrofagele"},{"id":"C","text":"Plasmocitele"},{"id":"D","text":"Leucocitele neutrofile polimorfonucleare"},{"id":"E","text":"Celulele dendritice"}],"correct":["D"],"pages":[121],"source":"set-2"},{"id":"set2-dtiEGslg","fingerprint":"09bdb23d07842c9b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele componente fac parte din matricea polimerică a biofilmului bacterian?","options":[{"id":"A","text":"Lipopolizaharide"},{"id":"B","text":"Polizaharide"},{"id":"C","text":"Acizi grași"},{"id":"D","text":"ADN extracelular"},{"id":"E","text":"Proteine și aminoacizi"}],"correct":["B","D","E"],"pages":[121],"source":"set-2"},{"id":"set2-YlDdvyic","fingerprint":"c583fd2078dae0e2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este considerată cea mai frecventă cauză a eșecului endodontic?","options":[{"id":"A","text":"Dezvoltarea unei infecții extraradiculare independente."},{"id":"B","text":"Suprainstrumentarea canalelor radiculare."},{"id":"C","text":"Infiltrația apicală și coronară."},{"id":"D","text":"Rezistența intrinsecă a Enterococcus faecalis la hidroxidul de calciu."},{"id":"E","text":"Prezența bacteriilor în canalele accesorii sub formă planctonică."}],"correct":["C"],"pages":[121],"source":"set-2"},{"id":"set2-EBTVUo3H","fingerprint":"098b22052d2cc361","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care dintre următoarele afirmații referitoare la rezistența germenilor și a biofilmului în context endodontic este corectă?","options":[{"id":"A","text":"Formele planctonice de bacterii prezintă o rezistență mult mai mare decât biofilmul."},{"id":"B","text":"Există o corelație între nivelurile de lipopolizaharide și prezența zonelor radiotransparente."},{"id":"C","text":"Biofilmele localizate în istmusurile intercanalare pot fi îndepărtate eficient prin preparație biomecanică."},{"id":"D","text":"Veziculele extracelulare au o determinanță antigenică diferită față de bacteria parentală."},{"id":"E","text":"Fimbriile sunt componente ale matricei polimerice care cresc aderența."}],"correct":["B"],"pages":[121],"source":"set-2"},{"id":"set2-ledyCMUT","fingerprint":"92e3cb4185301c7f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele entități nosologice sunt incluse în clasificarea patologiei pulpo-periapicale?","options":[{"id":"A","text":"Resorbția radiculară internă"},{"id":"B","text":"Pulpita ireversibilă"},{"id":"C","text":"Hipercementoza"},{"id":"D","text":"Pulpita reversibilă"},{"id":"E","text":"Parodontitele apicale"}],"correct":["B","D","E"],"pages":[104],"source":"set-2"},{"id":"set2-hnoGFU95","fingerprint":"f8a686c063afcf3b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt particularitățile anatomice care conferă o vulnerabilitate crescută țesutului pulpar?","options":[{"id":"A","text":"Un sistem nervos bine reprezentat"},{"id":"B","text":"O vascularizație de tip terminal"},{"id":"C","text":"Reducerea numărului de fibre nervoase aferente"},{"id":"D","text":"Prezența unei rețele vasculare anastomotice bogate"},{"id":"E","text":"Elasticitatea ridicată a pereților spațiului pulpar"}],"correct":["A","B"],"pages":[104],"source":"set-2"},{"id":"set2-SFA75viH","fingerprint":"0d15fc335220ea0b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Cum se manifestă răspunsul de apărare al complexului dentino-pulpar la diferite niveluri de organizare?","options":[{"id":"A","text":"La nivel dentinar se inițiază resorbția osteoclastică"},{"id":"B","text":"La nivel dentinar se produce scleroza tubulară"},{"id":"C","text":"La joncțiunea dentină-pulpă se constituie dentina terțiară"},{"id":"D","text":"La joncțiunea dentină-pulpă se constituie dentina primară"},{"id":"E","text":"În interiorul pulpei apare reacția inflamatorie"}],"correct":["B","C","E"],"pages":[104],"source":"set-2"},{"id":"set2-xLZl-hVl","fingerprint":"45ab51ae2eb20f23","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile anatomice și relațiile de contiguitate ale țesutului pulpar?","options":[{"id":"A","text":"Spațiul pulpar prezintă pereți rigizi care împiedică investigarea stării pulpare"},{"id":"B","text":"Are rapoarte cu parodonțiul prin foramenul apical și canalele laterale"},{"id":"C","text":"Pereții dentinari integri sunt permeabili la agenții patogeni"},{"id":"D","text":"Are rapoarte cu parodonțiul exclusiv prin canaliculele dentinare"},{"id":"E","text":"Îmbolnăvirile pulpare evoluează fără răsunet asupra parodonțiului"}],"correct":["A","B"],"pages":[104],"source":"set-2"},{"id":"set2-s3eUS3JZ","fingerprint":"17f67c81049ec912","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele forme anatomo-clinice sunt incluse în categoria pulpitelor ireversibile?","options":[{"id":"A","text":"Pulpitele cronice"},{"id":"B","text":"Hiperemia preinflamatorie"},{"id":"C","text":"Pulpita seroasă totală"},{"id":"D","text":"Pulpita acută seroasă parțială"},{"id":"E","text":"Pulpitele purulente"}],"correct":["A","C","E"],"pages":[104],"source":"set-2"},{"id":"set2-tzwN1YQU","fingerprint":"f43fd9da9b0954f7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este trăsătura clinică definitorie a pulpitei reversibile?","options":[{"id":"A","text":"Absența completă a simptomatologiei în condițiile unei percuții pozitive"},{"id":"B","text":"Reproductibilitatea clinică a sensibilității termice localizate, tranzitorii"},{"id":"C","text":"Reproductibilitatea clinică a unei dureri intense permanente"},{"id":"D","text":"Dezvoltarea unui țesut de granulație cunoscut sub denumirea de granulom intern Palazzi"},{"id":"E","text":"Imposibilitatea pulpei de a-și recapăta starea de sănătate, indiferent de tratamentul aplicat"}],"correct":["B"],"pages":[104],"source":"set-2"},{"id":"set2-LftlUofE","fingerprint":"07064736526f8806","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele forme anatomo-clinice reprezintă variante ale pulpitei cronice deschise?","options":[{"id":"A","text":"Propriu-zisă"},{"id":"B","text":"Purulentă"},{"id":"C","text":"Hiperplazică (granulom intern Palazzi)"},{"id":"D","text":"Granulomatoasă (polipoasă)"},{"id":"E","text":"Ulceroasă"}],"correct":["D","E"],"pages":[104],"source":"set-2"},{"id":"set2-J6PUhP2p","fingerprint":"ec3f7b10054bc619","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Absența simptomatologiei, în condițiile testelor de vitalitate pozitive, a percuției negative și a unui aspect radiologic nespecific, nu semnifică absența îmbolnăvirii pulpo-periapicale deoarece lipsa simptomatologiei este caracteristică și în:","options":[{"id":"A","text":"Pulpitele cronice și necroza pulpară necomplicată"},{"id":"B","text":"Pulpita reversibilă cu sensibilitate termică tranzitorie"},{"id":"C","text":"Hiperemia preinflamatorie și pulpita purulentă"},{"id":"D","text":"Pulpita ireversibilă caracterizată prin durere intensă"},{"id":"E","text":"Pulpita acută seroasă parțială și pulpita seroasă totală"}],"correct":["A"],"pages":[104],"source":"set-2"},{"id":"set2-yhS9w0Wb","fingerprint":"47643598e0876acd","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt trăsăturile clinice și evolutive specifice pulpitei reversibile?","options":[{"id":"A","text":"Efectele stimulilor chimici, termici și ale iritanților bacterieni se anulează printr-o atitudine terapeutică conservativă corectă"},{"id":"B","text":"Pulpa dentară nu își mai recapătă starea de sănătate, independent de tratamentele aplicate"},{"id":"C","text":"Evoluează invariabil și rapid către formarea unui granulom intern Palazzi"},{"id":"D","text":"Sensibilitatea termică manifestată este localizată și tranzitorie"},{"id":"E","text":"Pulpa dentară își poate recapăta starea de sănătate inițială în urma înlăturării cauzei"}],"correct":["A","D","E"],"pages":[104],"source":"set-2"},{"id":"set2-CUyqxuSH","fingerprint":"dcbbb1f63c873b93","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt consecințele acțiunii factorilor fizici și traumatici asupra sistemului pulpo-dentinar în timpul preparării cavităților?","options":[{"id":"A","text":"Secționarea prelungirilor odontoblastice reprezintă un factor traumatic care duce la dezintegrarea acestora."},{"id":"B","text":"Uscarea excesivă a dentinei determină fenomenul de aspirație al odontoblaștilor."},{"id":"C","text":"Uscarea excesivă blochează canaliculele dentinare prevenind orice modificare a structurilor odontoblastice."},{"id":"D","text":"Supraîncălzirea produce microhemoragii și dezintegrarea odontoblaștilor."},{"id":"E","text":"Supraîncălzirea induce modificări progresive cu hiperplazia prelungirilor odontoblastice."}],"correct":["A","B","D"],"pages":[105],"source":"set-2"},{"id":"set2-G-VkEs1g","fingerprint":"c99e8d396c7033a9","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele elemente sunt clasificate ca factori externi implicați în etiopatogenia pulpitelor?","options":[{"id":"A","text":"Agenții medicamentoși sunt clasificați drept factori externi toxici."},{"id":"B","text":"Fungii și virusurile sunt incluși în categoria agenților externi."},{"id":"C","text":"Afecțiunile intercurente reprezintă factori externi declanșatori cu acțiune sistemică."},{"id":"D","text":"Acizii și bazele reprezintă factori de agresiune chimică asupra sistemului pulpo-dentinar."},{"id":"E","text":"Substanțele oxidante și metalele grele reprezintă factori chimici cu potențial agresiv."}],"correct":["A","B","D","E"],"pages":[104],"source":"set-2"},{"id":"set2-wmsCH5qN","fingerprint":"f5adc6d728efb38b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care este mecanismul prin care procesele carioase și germenii patogeni acționează asupra sistemului pulpo-dentinar în dezvoltarea pulpitei?","options":[{"id":"A","text":"Bacteriile din procesul carios stimulează remineralizarea prelungirilor odontoblastice blocând canaliculele dentinare."},{"id":"B","text":"Pulpita retrogradă se instalează prin pătrunderea germenilor în canaliculele dentinare pe cale retrogradă."},{"id":"C","text":"Toxinele bacteriene difuzează în canaliculele dentinare inducând modificări regresive la nivelul prelungirilor odontoblastice."},{"id":"D","text":"Pătrunderea retrogradă a germenilor declanșează pulpita exclusiv în prezența acizilor proveniți din afecțiuni intercurente."},{"id":"E","text":"Toxinele bacteriene induc exclusiv modificări progresive de hipermineralizare a prelungirilor odontoblastice."}],"correct":["B","C"],"pages":[104],"source":"set-2"},{"id":"set2-hKSJhd6c","fingerprint":"064da1f6cfa8d71d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt modificările morfopatologice caracteristice pulpitei acute seroase parțiale?","options":[{"id":"A","text":"Prezența fenomenelor de vasodilatație și plasmexodie"},{"id":"B","text":"Fibroblaști cu semne de hiperactivitate metabolică și proliferare"},{"id":"C","text":"Odontoblaști care asociază vacuolizări și acumulări lipoidice"},{"id":"D","text":"Odontoblaști măriți de volum la nivelul stratului periferic pulpar"},{"id":"E","text":"Existența unui proces de marginație leucocitară"}],"correct":["A","C","E"],"pages":[105],"source":"set-2"},{"id":"set2-LjqZvVAL","fingerprint":"0bf76fb3867bfb5b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile clinice ale durerii specifice hiperemiei pulpare preinflamatorii?","options":[{"id":"A","text":"Este o durere vie, intensă, care cedează doar la administrarea de antialgice"},{"id":"B","text":"Caracterul său este strict localizat"},{"id":"C","text":"Prezintă o intensitate moderată în timpul manifestării clinice"},{"id":"D","text":"Durata crizei dureroase se extinde la intervale de minute până la ore"},{"id":"E","text":"Este provocată predominant de agenți termici reci și de excitanți chimici dulci"}],"correct":["B","C","E"],"pages":[105],"source":"set-2"},{"id":"set2-Xj52Xxjt","fingerprint":"5bd220072b845afb","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"În ce condiții pulpita acută seroasă parțială este considerată o afecțiune pulpară reversibilă?","options":[{"id":"A","text":"În prezența unei acumulări lipoidice masive în interiorul prelungirilor fibroblastice"},{"id":"B","text":"Atunci când testele de vitalitate ale pulpei devin negative pe parcursul examinării"},{"id":"C","text":"Când simptomatologia dureroasă a pacientului răspunde favorabil la administrarea de antialgice"},{"id":"D","text":"Dacă pacientul raportează un tratament restaurativ efectuat recent"},{"id":"E","text":"Dacă procesul inflamator existent este limitat exclusiv la nivelul pulpei coronare"}],"correct":["E"],"pages":[105],"source":"set-2"},{"id":"set2-kNrYYbJq","fingerprint":"e5a1533770f7cae3","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt opțiunile de tratament indicate pentru abordarea terapeutică a pulpitei acute seroase parțiale?","options":[{"id":"A","text":"Coafajul direct"},{"id":"B","text":"Inducerea \"restitutio ad integrum\" fără nicio intervenție terapeutică asumată"},{"id":"C","text":"Amputația vitală"},{"id":"D","text":"Coafajul indirect"},{"id":"E","text":"Extirparea vitală"}],"correct":["A","C","E"],"pages":[106],"source":"set-2"},{"id":"set2-mXt-hHaT","fingerprint":"027ff12bc48d83cb","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Cu care dintre următoarele entități patologice se realizează diagnosticul diferențial al pulpitei acute seroase parțiale?","options":[{"id":"A","text":"Pulpita purulentă"},{"id":"B","text":"Hiperemia preinflamatorie"},{"id":"C","text":"Hipersensibilitatea dentinară"},{"id":"D","text":"Pulpita cronică deschisă"},{"id":"E","text":"Pulpita acută seroasă totală"}],"correct":["A","B","E"],"pages":[105],"source":"set-2"},{"id":"set2-B8ln_Ohx","fingerprint":"bb8466d2ef357aad","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt modificările morfopatologice care caracterizează pulpita acută seroasă totală?","options":[{"id":"A","text":"Vasodilatație și plasmexodie."},{"id":"B","text":"Degenerescență odontoblastică."},{"id":"C","text":"Demielinizarea fibrelor nervoase."},{"id":"D","text":"Remielinizarea fibrelor nervoase."},{"id":"E","text":"Scăderea permeabilității vasculare."}],"correct":["A","B","C"],"pages":[106],"source":"set-2"},{"id":"set2-w9IBG1yV","fingerprint":"88f84b2777b159db","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele caracteristici sunt specifice durerii din pulpita acută seroasă totală?","options":[{"id":"A","text":"Iradiază în regiunea temporală, orbitară și submandibulară."},{"id":"B","text":"Cedează la administrarea de antialgice."},{"id":"C","text":"Depășește linia mediană."},{"id":"D","text":"Prezintă un caracter provocat."},{"id":"E","text":"Este violentă, insuportabilă și continuă."}],"correct":["A","D","E"],"pages":[106],"source":"set-2"},{"id":"set2-_SGxwHN4","fingerprint":"97e7a7b648f24f5b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt elementele care ajută la stabilirea diagnosticului diferențial al pulpitei acute seroase totale cu parodontita apicală acută seroasă?","options":[{"id":"A","text":"Mucoasa vestibulară este palidă în parodontita apicală acută seroasă."},{"id":"B","text":"Parodontita apicală acută seroasă este însoțită de o stare generală alterată."},{"id":"C","text":"Senzația de egresiune a dintelui."},{"id":"D","text":"Testele de vitalitate sunt negative în parodontita apicală acută seroasă."},{"id":"E","text":"Testele de vitalitate sunt pozitive în parodontita apicală acută seroasă."}],"correct":["B","C","D"],"pages":[107],"source":"set-2"},{"id":"set2-E2B3jUKD","fingerprint":"757f0202997d1df7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este mecanismul fiziopatologic ce declanșează durerea spontană și violentă în pulpita acută seroasă totală?","options":[{"id":"A","text":"Scăderea presiunii intratisulare ce decomprimă fibrele nervoase."},{"id":"B","text":"Presiunea exercitată asupra fibrei nervoase împreună cu acidoza locală."},{"id":"C","text":"Creșterea circulației venoase asociată cu alcaloza locală."},{"id":"D","text":"Regenerarea odontoblastică urmată de hipersensibilitate dentinară."},{"id":"E","text":"Acumularea exudatului purulent ce determină necroza imediată a țesuturilor."}],"correct":["B"],"pages":[106],"source":"set-2"},{"id":"set2-cc3d-vYo","fingerprint":"7f4c532a706cde57","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce trăsături definesc pulpitele ireversibile și conduita terapeutică asociată acestora?","options":[{"id":"A","text":"Reprezintă inflamații severe ale pulpei dentare care evoluează spre necroză."},{"id":"B","text":"Toate formele de pulpită începând cu pulpita acută seroasă totală sunt considerate ireversibile."},{"id":"C","text":"Aceste afecțiuni se caracterizează prin absența vasodilatației și a permeabilității vasculare."},{"id":"D","text":"Îndepărtarea factorului cauzal permite revenirea pulpei la starea de normalitate."},{"id":"E","text":"Tratamentul pentru pulpita acută seroasă totală constă în extirparea vitală."}],"correct":["A","B","E"],"pages":[106],"source":"set-2"},{"id":"set2-VwK0E6Oa","fingerprint":"d2b69a9021df671a","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele elemente morfopatologice sunt caracteristice pulpitei acute purulente?","options":[{"id":"A","text":"Acumularea de fibre de colagen dense"},{"id":"B","text":"Transformarea purulentă sub formă de flegmon pulpar"},{"id":"C","text":"Încărcările lipidice"},{"id":"D","text":"Absența durerii la percuția în ax"},{"id":"E","text":"Diapedeza leucocitară"}],"correct":["B","C","E"],"pages":[107],"source":"set-2"},{"id":"set2-M5pxcyPS","fingerprint":"0800a3f82be8c892","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce trăsături definesc durerea și simptomatologia din pulpita acută purulentă?","options":[{"id":"A","text":"Exacerbare prin creșterea fluxului sangvin indusă de căldură"},{"id":"B","text":"Caracter pulsatil"},{"id":"C","text":"Intensitate violentă"},{"id":"D","text":"Declanșare exclusiv pe timpul zilei"},{"id":"E","text":"Durată limitată la câteva minute"}],"correct":["A","B","C"],"pages":[107],"source":"set-2"},{"id":"set2-plzrMw5x","fingerprint":"22b5be6acd10b336","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este reacția caracteristică a pulpitei acute purulente la aplicarea stimulilor termici?","options":[{"id":"A","text":"Durerea este exacerbată atât de cald, cât și de rece"},{"id":"B","text":"Durerea se calmează la aplicarea stimulilor calzi"},{"id":"C","text":"Durerea diminuă semnificativ la aplicarea stimulilor reci"},{"id":"D","text":"Răspunsul dureros este absent la variațiile termice"},{"id":"E","text":"Durerea este influențată exclusiv de percuția în ax, nu de temperatură"}],"correct":["C"],"pages":[107],"source":"set-2"},{"id":"set2-alHIL0oQ","fingerprint":"15ed32e9905ee5f7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele entități nosologice fac parte din diagnosticul diferențial al pulpitei acute purulente?","options":[{"id":"A","text":"Parodontita apicală simptomatică"},{"id":"B","text":"Parodontita apicală asimptomatică"},{"id":"C","text":"Pulpita purulentă"},{"id":"D","text":"Necroza pulpară"},{"id":"E","text":"Pulpita seroasă"}],"correct":["A","C","E"],"pages":[107],"source":"set-2"},{"id":"set2-n5KdZL0p","fingerprint":"9e663904ee149e65","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce atitudine terapeutică este indicată ca tratament pentru pulpita acută purulentă?","options":[{"id":"A","text":"Amputația vitală"},{"id":"B","text":"Extirparea vitală"},{"id":"C","text":"Coafajul pulpar direct"},{"id":"D","text":"Drenajul endodontic deschis"},{"id":"E","text":"Tratamentul medicamentos cu antibiotice sistemice"}],"correct":["B"],"pages":[107],"source":"set-2"},{"id":"set2-nYtr988T","fingerprint":"4a4672216bc70af5","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt criteriile clinice și paraclinice utilizate pentru stabilirea diagnosticului pozitiv de pulpită cronică deschisă ulceroasă?","options":[{"id":"A","text":"Răspuns pozitiv la testele de vitalitate efectuate la intensități mari"},{"id":"B","text":"Sângerare la înțeparea pulpei cu sonda"},{"id":"C","text":"Sensibilitate și durere severă la percuția în ax"},{"id":"D","text":"Lipsa durerii"},{"id":"E","text":"Lipsă de sensibilitate și absența sângerării la explorare"}],"correct":["A","B","D"],"pages":[107,108,109],"source":"set-2"},{"id":"set2-6Gsfe3iv","fingerprint":"7f22d672bdc47de5","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este caracteristica morfopatologică definitorie a pulpitei cronice deschise polipoase?","options":[{"id":"A","text":"Prezența unei suprafețe ulcerate acoperite de depozite de fibrină și înconjurate de zone de necroză"},{"id":"B","text":"Acoperirea constantă a suprafeței pulpare cu un epiteliu simplu cilindric"},{"id":"C","text":"Absența completă a proceselor de epitelizare la nivelul țesutului de granulație hipertrofiat în toate stadiile evolutive"},{"id":"D","text":"Proliferarea unui țesut de granulație sub forma unei formațiuni polipoase hipertrofiate care se extinde în afara camerei pulpare"},{"id":"E","text":"Extinderea procesului inflamator cronic exclusiv pe fondul unei reactivități generale scăzute a organismului"}],"correct":["D"],"pages":[107,108,109],"source":"set-2"},{"id":"set2-pF-xvS3I","fingerprint":"44449e6f57a33982","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce caracteristici pot fi identificate la examenul obiectiv al unui pacient cu pulpită cronică deschisă polipoasă?","options":[{"id":"A","text":"Baza de inserție a formațiunii polipoase este localizată exclusiv la nivelul mucoasei gingivale"},{"id":"B","text":"Polip pulpar de culoare roz, cu suprafața netedă și lucioasă, reprezentând forma epitelizată"},{"id":"C","text":"Înțepare nedureroasă la suprafață, dar cu răspuns pozitiv în profunzime, însoțită de sângerare abundentă"},{"id":"D","text":"Polip epitelizat de culoare roșie hemoragică, acoperit cu depozite abundente de fibrină"},{"id":"E","text":"Prezența unei formațiuni de consistență dură și nedepresibilă care ocupă cavitatea carioasă"}],"correct":["B","C"],"pages":[107,108,109],"source":"set-2"},{"id":"set2-iLsimHrw","fingerprint":"9cd011933917c862","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt particularitățile simptomatologice și evolutive asociate pulpitei cronice deschise ulceroase?","options":[{"id":"A","text":"Durerea apărută în episoadele de reacutizare are o intensitate ridicată din cauza numărului crescut de fibre nervoase"},{"id":"B","text":"Masticația este realizată preferențial pe partea afectată datorită analgeziei complete locale"},{"id":"C","text":"Dezvoltarea procesului inflamator cronic are loc pe fondul unei capacități de apărare individuale scăzute"},{"id":"D","text":"Obliterarea cavității cu resturi alimentare poate conduce la declanșarea unor fenomene de reacutizare"},{"id":"E","text":"Suprafața pulpară prezintă o tendință accelerată de vindecare odată cu formarea țesutului de granulație"}],"correct":["C","D"],"pages":[107,108,109],"source":"set-2"},{"id":"set2-jRCTl6e4","fingerprint":"ed736c7a76ebae70","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu mecanismele de dezvoltare și criteriile de diagnostic diferențial pentru pulpita cronică deschisă polipoasă?","options":[{"id":"A","text":"Polipul gingival se diferențiază de polipul pulpar prin faptul că are baza de inserție în continuarea pulpei dentare"},{"id":"B","text":"Muchia de dentină ascuțită situată la nivelul deschiderii camerei pulpare constituie un stimul pentru dezvoltarea polipului pulpar"},{"id":"C","text":"Diferențierea față de necroza pulpară este stabilită prin prezența sângerării și a sensibilității în profunzime la formațiunea polipoasă"},{"id":"D","text":"Diagnosticul diferențial cu pulpita cronică deschisă ulceroasă se realizează prin identificarea unei percuții în ax pozitive la forma ulceroasă"},{"id":"E","text":"Percuția în ax declanșează o reacție intens dureroasă, fiind esențială pentru diagnosticul pozitiv"}],"correct":["B","C"],"pages":[107,108,109],"source":"set-2"},{"id":"set2-JZJxIv-w","fingerprint":"eda33203db1e3606","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt elementele clinice și evolutive comune ale pulpitelor cronice închise?","options":[{"id":"A","text":"Lipsa țesutului de granulație"},{"id":"B","text":"Frecvență ridicată de apariție"},{"id":"C","text":"Simptomatologie dureroasă accentuată"},{"id":"D","text":"Evoluție lentă"},{"id":"E","text":"Cameră pulpară închisă"}],"correct":["D","E"],"pages":[109],"source":"set-2"},{"id":"set2--kg-YWPs","fingerprint":"3cb04a4098f889ca","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce modificări pot fi identificate la examenul obiectiv și în cadrul testelor diagnostice în pulpita cronică închisă propriu-zisă?","options":[{"id":"A","text":"Prezența vaselor de neoformație la nivelul țesutului pulpar"},{"id":"B","text":"Răspuns pozitiv la testele de vitalitate la intensități foarte mari"},{"id":"C","text":"Sensibilitate extremă la palparea cu sonda a pulpei expuse"},{"id":"D","text":"Sângerare abundentă la deschiderea camerei pulpare și înțeparea cu sonda"},{"id":"E","text":"Prezența unei cavități carioase cu dentină intens colorată în negru pe fundul acesteia"}],"correct":["A","B","D"],"pages":[109],"source":"set-2"},{"id":"set2-GYFkBiZo","fingerprint":"1231ec73ab1cb3a6","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este un aspect radiologic caracteristic pentru pulpita cronică închisă hiperplazică?","options":[{"id":"A","text":"Modificarea conturului canalului radicular, cu aspect segmentar și asimetric"},{"id":"B","text":"Apariția unei pete roz la nivelul smalțului radicular"},{"id":"C","text":"Prezența unor lacune formate de osteoclaste pe suprafața externă a rădăcinii"},{"id":"D","text":"Resorbție radiculară externă cu aspect asimetric"},{"id":"E","text":"Modificarea segmentară a conturului canalului radicular, cu aspect simetric"}],"correct":["E"],"pages":[109],"source":"set-2"},{"id":"set2-a8EeNNle","fingerprint":"cba0e6c86ef9b0b7","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt afirmațiile adevărate privind etiologia și particularitățile de tratament în pulpita cronică închisă hiperplazică?","options":[{"id":"A","text":"Tratamentul de elecție constă în extirparea vitală"},{"id":"B","text":"Debridarea și instrumentarea canalului se realizează cu ușurință"},{"id":"C","text":"Există un risc crescut de fractură corono-radiculară în timpul preparării canalului"},{"id":"D","text":"Afecțiunea se dezvoltă din infecții bacteriene generalizate la nivel pulpar"},{"id":"E","text":"Etiologia include traumatisme, precum luxațiile dentare"}],"correct":["A","C","E"],"pages":[109],"source":"set-2"},{"id":"set2-Gwbp5o_R","fingerprint":"c5a89d29a11930ba","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Diagnosticul diferențial al pulpitei cronice închise propriu-zise include următoarele afecțiuni:","options":[{"id":"A","text":"Pulpita cronică deschisă ulceroasă"},{"id":"B","text":"Resorbția radiculară externă"},{"id":"C","text":"Necroza pulpară"},{"id":"D","text":"Pulpita acută seroasă"},{"id":"E","text":"Pulpita cronică închisă granulomatoasă"}],"correct":["A","C","E"],"pages":[109],"source":"set-2"},{"id":"set2-juZ77gAK","fingerprint":"e1512708b465d874","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este mecanismul fiziopatologic și evolutiv descris în dinamica îmbolnăvirii pulpare?","options":[{"id":"A","text":"Inflamația pulpară cronică este un proces ireversibil care se transformă inevitabil în resorbție osoasă"},{"id":"B","text":"Țesutul de granulație din pulpita cronică închisă este substituit rapid de membrană conjunctivă acelulară"},{"id":"C","text":"Starea imunologică pulpară condiționează transformarea inflamației acute în inflamație cronică și acutizarea celei cronice"},{"id":"D","text":"Pulpita acută se poate transforma în inflamație cronică exclusiv în absența încărcăturii bacteriene"},{"id":"E","text":"Dentinoclastele proliferează exclusiv sub influența inflamației acute pulpare nespecifice"}],"correct":["C"],"pages":[109],"source":"set-2"},{"id":"set2-YbxqRWIw","fingerprint":"d4475dd9d4dd5298","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile procedurale și materialele utilizate în cadrul pulpotomiei vitale la dinții permanenți?","options":[{"id":"A","text":"Pentru înlăturarea pulpei coronare, utilizarea instrumentarului rotativ este preferabilă celei cu instrumentar manual."},{"id":"B","text":"Aplicarea de ciment cu ionomeri de sticlă peste stratul de MTA permite realizarea restaurării coronare definitive în aceeași ședință."},{"id":"C","text":"Stratul de ciment disilicat de calciu aplicat deasupra pulpei radiculare trebuie să aibă o grosime de aproximativ 3-4 mm."},{"id":"D","text":"Biodentine este un ciment bioceramic conceput și indicat inițial ca un înlocuitor pentru smalțul dentar."},{"id":"E","text":"Materialele utilizate pentru coafarea pulpei radiculare remanente trebuie să asigure sigilarea, să fie biocompatibile și să aibă proprietăți antimicrobiene."}],"correct":["B","E"],"pages":[110],"source":"set-2"},{"id":"set2--hscDd-5","fingerprint":"0a64163ab7bb687e","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce conduită se adoptă în cadrul pulpotomiei de urgență la dinții pluriradiculari, după irigarea camerei pulpare cu hipoclorit de sodiu?","options":[{"id":"A","text":"Se utilizează o freză sferică pentru a secționa pulpa la nivelul treimii apicale a rădăcinii."},{"id":"B","text":"Se introduce ciment bioceramic bazat pe disilicat de calciu în strat de 1-2 mm la nivelul orificiilor canalelor radiculare."},{"id":"C","text":"Se aplică o pastă pe bază de hidroxid de calciu urmată de o obturație coronară temporară necompresivă."},{"id":"D","text":"Se aplică un strat de ciment cu ionomeri de sticlă modificat cu rășini pentru a permite restaurarea coronară definitivă în aceeași ședință."},{"id":"E","text":"Se obturează complet canalul radicular prin preparație chemo-mecanică completă."}],"correct":["C"],"pages":[110],"source":"set-2"},{"id":"set2-C3AdVTWc","fingerprint":"5f52dba08ffc885d","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații pentru realizarea pulpectomiei vitale (extirpării vitale)?","options":[{"id":"A","text":"Stările fiziologice speciale."},{"id":"B","text":"Cooperarea deficitară a pacientului."},{"id":"C","text":"Dinții situați în focare de fractură."},{"id":"D","text":"Dinții cu abraziune patologică."},{"id":"E","text":"Pulpitele retrograde."}],"correct":["C","D","E"],"pages":[110],"source":"set-2"},{"id":"set2-3klLv_3C","fingerprint":"3f531be50c6310df","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următorii factori sunt clasificați drept cauze locale ale hemoragiei în timpul pulpectomiei vitale?","options":[{"id":"A","text":"Suprainstrumentarea canalului radicular."},{"id":"B","text":"Afecțiunile hepatice grave."},{"id":"C","text":"Lezarea parodonțiului marginal."},{"id":"D","text":"Crearea unor căi false."},{"id":"E","text":"Diatezele hemoragipare."}],"correct":["A","C","D"],"pages":[111],"source":"set-2"},{"id":"set2-DyUBzeaB","fingerprint":"c1a91e111fafb115","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este criteriul care confirmă succesul terapeutic în urma monitorizării unei pulpotomii?","options":[{"id":"A","text":"Dispariția durerii, corelată cu necroza completă și aseptică a pulpei radiculare."},{"id":"B","text":"Menținerea intactă a porțiunii coronare a pulpei și extirparea celei radiculare."},{"id":"C","text":"Izolarea corectă a dintelui cu digă și absența contaminării în ședințele ulterioare."},{"id":"D","text":"Absența simptomatologiei pulpare și periapicale, însoțită de menținerea vitalității pulpei."},{"id":"E","text":"Reducerea hemoragiei la emergența canalelor radiculare după utilizarea frezei sferice."}],"correct":["D"],"pages":[109],"source":"set-2"},{"id":"set2-XD_KklhH","fingerprint":"1397c314548864f5","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt afirmațiile adevărate privind necroza pulpară și consecințele sale fiziopatologice?","options":[{"id":"A","text":"Necroza complicată reprezintă mortificarea septică a pulpei dentare sub influența germenilor anaerobi."},{"id":"B","text":"În perioada în care bacteriile rămân cantonate în spațiul endodontic, afecțiunea este asimptomatică."},{"id":"C","text":"Necroza pulpară neinfectată determină o inflamație severă în țesutul periapical."},{"id":"D","text":"Pulpa necrotică reprezintă un mediu nefavorabil pentru dezvoltarea bacteriilor datorită lipsei de vascularizație."},{"id":"E","text":"Extinderea bacteriilor la nivelul spațiului periodontal duce la apariția durerilor spontane și la percuție."}],"correct":["A","B","E"],"pages":[111],"source":"set-2"},{"id":"set2-Vafjccy7","fingerprint":"50c4dc39331a4611","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următorii factori reprezintă factori locali implicați în etiopatogenia necrozei pulpare?","options":[{"id":"A","text":"Traumatismele de intensitate mare care duc la ruperea pachetului vascular pulpar"},{"id":"B","text":"Inflamația pulpară acută sau cronică ce duce la o necroză de lichefacție"},{"id":"C","text":"Traumatismele de intensitate mică și repetată care duc la compresia pachetului vasculo-nervos"},{"id":"D","text":"Ischemia apărută în cadrul patologiei generale"},{"id":"E","text":"Spasmele vasculare prelungite"}],"correct":["A","B","C"],"pages":[111],"source":"set-2"},{"id":"set2-g_mTpRTO","fingerprint":"ef3a7adc379cf337","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Cum este definită mortificarea septică a pulpei dentare sub influența germenilor anaerobi?","options":[{"id":"A","text":"Necroză de lichefacție"},{"id":"B","text":"Necroză complicată"},{"id":"C","text":"Mortificare aseptică"},{"id":"D","text":"Spasm vascular prelungit"},{"id":"E","text":"Ischemie pulpară localizată"}],"correct":["B"],"pages":[111],"source":"set-2"},{"id":"set2-OxRU_lCX","fingerprint":"de0179186d72f8a1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt consecințele dezvoltării și extinderii bacteriilor în spațiul endodontic și periodontal în evoluția necrozei pulpare?","options":[{"id":"A","text":"Difuzează rapid în spațiul periodontal, generând simptomatologie dureroasă imediată."},{"id":"B","text":"Rămân permanent limitate în spațiul endodontic, împiedicând inflamația parodonțiului apical."},{"id":"C","text":"Cantonează o perioadă în spațiul endodontic menținând afecțiunea asimptomatică."},{"id":"D","text":"Extinderea în spațiul periodontal duce la apariția durerilor spontane."},{"id":"E","text":"Extinderea lor la nivelul spațiului periodontal determină apariția durerilor la percuție."}],"correct":["C","D","E"],"pages":[111],"source":"set-2"},{"id":"set2-YL0FEJMq","fingerprint":"287822af4e801b14","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt tipurile de necroză pulpară recunoscute în funcție de extinderea procesului și gradul de interesare a spațiilor endodontice sau parodontale?","options":[{"id":"A","text":"Totală"},{"id":"B","text":"Complicată"},{"id":"C","text":"Simplă"},{"id":"D","text":"Parțială"},{"id":"E","text":"Ireversibilă"}],"correct":["A","B","C","D"],"pages":[112],"source":"set-2"},{"id":"set2-IHbxPPZ3","fingerprint":"37c225c1b616dd48","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele elemente clinice și paraclinice contribuie la stabilirea diagnosticului pozitiv de necroză pulpară?","options":[{"id":"A","text":"Examen radiologic cu absența modificărilor la nivelul parodonțiului apical"},{"id":"B","text":"Modificarea de culoare a coroanei dentare"},{"id":"C","text":"Lipsa sensibilității la palparea în camera pulpară și în canalele radiculare"},{"id":"D","text":"Examen bacteriologic constant pozitiv în forma simplă"},{"id":"E","text":"Teste de vitalitate pozitive la intensități mari"}],"correct":["A","B","C"],"pages":[112],"source":"set-2"},{"id":"set2-EqNCKcOQ","fingerprint":"88fc1a248175c5a6","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este elementul definitoriu pentru a diferenția necroza pulpară de o parodontită apicală asimptomatică?","options":[{"id":"A","text":"Prezența unei radiotransparențe periapicale la examenul radiologic"},{"id":"B","text":"Răspunsul pozitiv la testele de vitalitate termice"},{"id":"C","text":"Prezența sângerării în profunzimea canalului radicular"},{"id":"D","text":"Congestia mucoasei vestibulare în dreptul dintelui afectat"},{"id":"E","text":"Durerea exacerbată la percuția în ax a dintelui"}],"correct":["A"],"pages":[112],"source":"set-2"},{"id":"set2-Zyio8Pck","fingerprint":"aba0415745fc9e8c","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt constatările clinice obiective asociate unui dinte cu necroză pulpară?","options":[{"id":"A","text":"Percuție în ax pozitivă"},{"id":"B","text":"Coroană dentară de culoare brună sau cenușie"},{"id":"C","text":"Lipsa sensibilității pe întreg traseul canalului radicular"},{"id":"D","text":"Palparea prin sondare a canalelor radiculare nedureroasă"},{"id":"E","text":"Sângerare abundentă la deschiderea camerei pulpare"}],"correct":["B","C","D"],"pages":[112],"source":"set-2"},{"id":"set2-c01vWXfR","fingerprint":"4741db57a6f81b85","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce trăsături diferențiază necroza pulpară complicată de cea simplă?","options":[{"id":"A","text":"În necroza complicată, camera pulpară se prezintă frecvent deschisă"},{"id":"B","text":"Necroza simplă prezintă constant modificări radiologice apicale"},{"id":"C","text":"Necroza complicată interesează exclusiv spațiul endodontic"},{"id":"D","text":"Necroza complicată se extinde în spațiul periodontal"},{"id":"E","text":"Examenul bacteriologic este pozitiv în necroza complicată"}],"correct":["A","D","E"],"pages":[112],"source":"set-2"},{"id":"set2-TLBUsyt5","fingerprint":"1c4fc5539d31c993","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt echivalențele acceptate în literatura internațională de specialitate pentru formele clinice ale parodontitei apicale acute?","options":[{"id":"A","text":"Parodontita apicală purulentă este echivalentă cu abcesul acut apical."},{"id":"B","text":"Parodontita apicală hiperemică este echivalentă cu parodontita apicală."},{"id":"C","text":"Parodontita apicală purulentă este echivalentă cu parodontita apicală."},{"id":"D","text":"Parodontita apicală hiperemică este echivalentă cu abcesul acut apical."},{"id":"E","text":"Parodontita apicală seroasă este echivalentă cu abcesul acut apical."}],"correct":["A","B","E"],"pages":[112],"source":"set-2"},{"id":"set2-ogoWW8vK","fingerprint":"a6aa0c286ff67bd1","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este caracteristica bacteriologică și fiziopatologică principală la dinții care prezintă parodontită apicală asimptomatică?","options":[{"id":"A","text":"Leucocitele mononucleare sunt celulele care împiedică invazia bacteriilor în apex în fazele incipiente."},{"id":"B","text":"Leziunile periapicale conțin o floră microbiană organizată predominant sub formă de biofilm."},{"id":"C","text":"Invazia microorganismelor în periapex se produce rapid din cauza absenței răspunsului imun celular."},{"id":"D","text":"Microorganismele din biofilme sunt cantonate exclusiv în leziunile periapicale."},{"id":"E","text":"Microorganismele sunt cantonate în sistemul endodontic și canaliculele dentinare, iar leziunile periapicale sunt lipsite de germeni."}],"correct":["E"],"pages":[112],"source":"set-2"},{"id":"set2-QcXck9Zv","fingerprint":"432afe28e57739d9","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt afirmațiile valabile privind diagnosticul și structurile afectate în inflamațiile periapicale de cauză endodontică?","options":[{"id":"A","text":"Diagnosticul se bazează exclusiv pe examenul radiografic și testele de vitalitate pulpară."},{"id":"B","text":"Ligamentul periodontal rămâne intact pe parcursul infecțiilor bacteriene periapicale."},{"id":"C","text":"Inflamațiile periapicale de cauză endodontică afectează osul alveolar."},{"id":"D","text":"Diagnosticul se bazează doar pe semne clinice și simptome, precum durerea și sensibilitatea la percuție."},{"id":"E","text":"Procesul inflamator periradicular afectează cementul radicular."}],"correct":["C","D","E"],"pages":[112],"source":"set-2"},{"id":"set2-yiasJX4B","fingerprint":"78cfb99e5cc8bad3","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care sunt formele clinice ale parodontitei apicale acute recunoscute de Școala românească de endodonție?","options":[{"id":"A","text":"Abcesul apical acut, abcesul apical cronic și parodontita apicală seroasă."},{"id":"B","text":"Parodontita apicală asimptomatică, hiperemică și purulentă."},{"id":"C","text":"Parodontita apicală hiperemică, acută și cronică."},{"id":"D","text":"Parodontita apicală asimptomatică, seroasă și cronică."},{"id":"E","text":"Parodontita apicală hiperemică, seroasă și purulentă."}],"correct":["E"],"pages":[112],"source":"set-2"},{"id":"set2-cdsx6Uw2","fingerprint":"ab6f288a5bf63a34","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce fenomene fiziopatologice caracterizează parodontita apicală asimptomatică și infecțiile de lungă durată asociate?","options":[{"id":"A","text":"Invazia microorganismelor în periapex poate avea loc pe fondul ineficienței mecanismelor de apărare în infecțiile de lungă durată."},{"id":"B","text":"Mecanismele de apărare devin mai puțin eficiente în infecțiile de lungă durată cu o floră permanentă."},{"id":"C","text":"Sistemul defensiv mobilizat pentru a împiedica invazia bacteriilor în apex este reprezentat de leucocitele polimorfonucleare."},{"id":"D","text":"Leucocitele polimorfonucleare sunt absente în parodontita apicală asimptomatică, permițând colonizarea timpurie a osului alveolar."},{"id":"E","text":"În stadiile asimptomatice, microorganismele colonizează sistemul endodontic și leziunile periapicale în mod egal."}],"correct":["A","B","C"],"pages":[112],"source":"set-2"},{"id":"set2-Eju_fQsE","fingerprint":"6c89ac30704b08a2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt factorii etiologici implicați în apariția parodontitei apicale acute hiperemice?","options":[{"id":"A","text":"Agenții microbieni."},{"id":"B","text":"Agenții chimici reprezentați de medicația din pungile parodontale."},{"id":"C","text":"Traumatismele majore cu fracturi radiculare oblice."},{"id":"D","text":"Materialele de obturație coronară din compozit cu polimerizare incompletă."},{"id":"E","text":"Microtraumatismele provocate de bruxism sau supra-instrumentare."}],"correct":["A","B","E"],"pages":[113],"source":"set-2"},{"id":"set2-YW77x2Rq","fingerprint":"81d78a618cf5a8a9","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente clinice și radiologice contribuie la diagnosticul pozitiv al parodontitei apicale acute hiperemice?","options":[{"id":"A","text":"Radiotransparența periapicală în cazurile de parodontită cronică acutizată."},{"id":"B","text":"Sensibilitatea la percuția în ax."},{"id":"C","text":"Simptomatologia de pulpită parțială."},{"id":"D","text":"Evidențierea radiologică a unei obturații de canal cu depășire."},{"id":"E","text":"Paloarea mucoasei în dreptul apexului."}],"correct":["A","B","D"],"pages":[113],"source":"set-2"},{"id":"set2-JvZ-cbrI","fingerprint":"e126d0bf9ef7c67b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Cu ce afecțiuni se face diagnosticul diferențial al parodontitei apicale acute hiperemice?","options":[{"id":"A","text":"Abcesul acut apical."},{"id":"B","text":"Pulpita acută purulentă."},{"id":"C","text":"Parodontita apicală cronică fibroasă."},{"id":"D","text":"Necroza pulpară."},{"id":"E","text":"Pulpita acută seroasă totală."}],"correct":["A","B","E"],"pages":[113],"source":"set-2"},{"id":"set2-czm30KgE","fingerprint":"be1531a68a910b87","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este atitudinea terapeutică de primă intenție și evoluția biologică în cazul parodontitei apicale hiperemice consecutive unei obturații de canal cu depășire?","options":[{"id":"A","text":"Tratamentul constă în administrarea de antiinflamatoare și antialgice, urmată de reparație tisulară după completarea prizei materialului în absența bacteriilor."},{"id":"B","text":"Sealerul menține un efect biologic iritant indefinit, necesitând retratamentul endodontic obligatoriu."},{"id":"C","text":"Se recomandă exclusiv antibioterapie sistemică pentru a preveni infecția bacteriană secundară."},{"id":"D","text":"Se indică rezecția apicală imediată din cauza efectului iritant permanent al sealerului proaspăt mixat."},{"id":"E","text":"Tratamentul implică administrarea de corticosteroizi locali pentru a contracara reacția inflamatorie majoră produsă de o interfață mare a sealerului."}],"correct":["A"],"pages":[113],"source":"set-2"},{"id":"set2-IIjm8FHK","fingerprint":"9cc55ba863dfe4d4","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile reacției tisulare la contactul cu sealerul utilizat în obturațiile de canal?","options":[{"id":"A","text":"Reacția de priză a materialului este completă după câteva ore."},{"id":"B","text":"Sealerul are un potențial efect iritant în stadiul proaspăt mixat."},{"id":"C","text":"Materialul cu priză completă aparent nu prezintă efecte biologice."},{"id":"D","text":"Reparația tisulară se instalează odată cu completarea prizei materialului, exclusiv în prezența unei flore microbiene minime."},{"id":"E","text":"O interfață mică a materialului determină o reacție inflamatorie redusă."}],"correct":["B","C","E"],"pages":[113],"source":"set-2"},{"id":"set2-zZ0zGjkG","fingerprint":"148acc1a198c1264","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect semnele subiective din parodontita apicală acută seroasă?","options":[{"id":"A","text":"Durerea este descrisă ca fiind lancinantă și permanentă."},{"id":"B","text":"Durerea se remite rapid și complet în urma administrării de calmante uzuale."},{"id":"C","text":"Evoluția durerii este progresivă, atingând un prag insuportabil într-un interval de 24-48 de ore."},{"id":"D","text":"Episodul algic are un caracter strict pulsatil, asociat cu o tumefacție circumscrisă."},{"id":"E","text":"Intensitatea algică este exacerbată de aplecatul înainte și de căldura pernei."}],"correct":["A","C","E"],"pages":[113,114],"source":"set-2"},{"id":"set2-82XlEHtZ","fingerprint":"def6684d2721b5c2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"În cazul abcesului acut periapical, localizarea edemului și a tumefacției se corelează cu poziția dintelui cauzal. Care dintre următoarele asocieri anatomice sunt clinic valide?","options":[{"id":"A","text":"Afectarea caninilor superiori determină tumefacția aripei nasului și a regiunii palpebrale."},{"id":"B","text":"Implicarea dinților frontali superiori generează edem la nivelul buzei superioare."},{"id":"C","text":"Afectarea dinților laterali inferiori este urmată de tumefacție în regiunea geniană."},{"id":"D","text":"Patologia premolarilor și molarilor superiori produce edem în regiunea mentonieră."},{"id":"E","text":"Implicarea dinților frontali inferiori se manifestă prin edemul buzei inferioare și al regiunii mentoniere."}],"correct":["A","B","E"],"pages":[113,114],"source":"set-2"},{"id":"set2-urfDc46S","fingerprint":"d3329e6efa9e65ba","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Diagnosticul diferențial al parodontitei apicale acute seroase include evaluarea mai multor afecțiuni de la nivelul teritoriului oro-maxilo-facial. Care sunt enunțurile clinice corespunzătoare acestui demers diagnostic?","options":[{"id":"A","text":"Nevralgia de trigemen se distinge printr-o durere constantă, care se remite la analgezice ușoare."},{"id":"B","text":"Parodontita apicală acută purulentă prezintă un edem difuz, cu margini greu de delimitat."},{"id":"C","text":"Durerea din nevralgia de trigemen apare sub formă de crize și persistă chiar și după tratamentul corect al patologiei odontale."},{"id":"D","text":"Diagnosticul cu pulpita acută se bazează pe existența unor teste de vitalitate pozitive."},{"id":"E","text":"Foliculita dinților incluși se regăsește printre entitățile cu care se realizează diagnosticul diferențial."}],"correct":["C","D","E"],"pages":[113,114],"source":"set-2"},{"id":"set2-v3MYOobR","fingerprint":"c9b2694e0c01643f","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Diagnosticul pozitiv al parodontitei apicale acute seroase se fundamentează pe cumularea unor elemente clinice și generale. Care dintre următoarele reprezintă criterii valide pentru stabilirea acestuia?","options":[{"id":"A","text":"Simptomatologia principală este dominată exclusiv de o durere de tip pulsatil."},{"id":"B","text":"Examenul clinic decelează o percuție în ax pozitivă."},{"id":"C","text":"Testele de vitalitate indică un răspuns puternic pozitiv."},{"id":"D","text":"Pacientul prezintă o stare generală alterată, caracterizată prin febră și frisoane."},{"id":"E","text":"Se constată prezența tumefacției la nivelul mucoasei și al tegumentelor."}],"correct":["B","D","E"],"pages":[113,114],"source":"set-2"},{"id":"set2-uldixOVh","fingerprint":"b84db1223080c19a","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Parodontita apicală acută seroasă este o patologie inflamatorie ce asociază semne obiective și subiective bine definite. Care sunt manifestările asociate în mod specific acestei etape patologice?","options":[{"id":"A","text":"Pacientul evită mișcările capului și prezintă rigiditate facială."},{"id":"B","text":"Tumefacția asociată prezintă un contur strict delimitat și un aspect ferm circumscris încă din stadiul incipient."},{"id":"C","text":"Examenul obiectiv decelează absența totală a adenopatiei la nivelul ganglionilor regionali."},{"id":"D","text":"La inspecție se observă congestia mucoasei în dreptul rădăcinii dintelui implicat."},{"id":"E","text":"Durerea dezvoltă un tipar iradiant, extinzându-se frecvent spre orbită, regiunea temporală, auriculară, mandibulară sau cervicală."}],"correct":["A","D","E"],"pages":[113,114],"source":"set-2"},{"id":"set2-n6GdoJ1R","fingerprint":"322ea9a641edea6b","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care dintre următoarele manifestări clinice este caracteristică stadiului supurativ al abcesului acut apical, diferențiindu-l de primul stadiu evolutiv?","options":[{"id":"A","text":"Prezența semnului godeului la examinarea tumefacției."},{"id":"B","text":"Stare generală nealterată, în pofida hipertermiei locale."},{"id":"C","text":"Tegumente calde, destinse, însoțite de absența semnului godeului."},{"id":"D","text":"Creșterea tumefacției intraorale și scăderea mobilității dentare în stadiul submucos."},{"id":"E","text":"Exacerbarea durerii odată cu traversarea periostului de către procesul infecțios."}],"correct":["A"],"pages":[115],"source":"set-2"},{"id":"set2-LZKl4IP5","fingerprint":"8375c2ef31a31da8","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt caracteristicile evolutive ale durerii în funcție de stadiul de progresie tisulară al abcesului acut apical?","options":[{"id":"A","text":"În stadiul endoosos, durerea are un caracter iradiat."},{"id":"B","text":"În stadiul endoosos, durerea este strict localizată la nivelul dintelui cauzal."},{"id":"C","text":"Fistulizarea procesului supurativ determină o exacerbare imediată a durerii și a febrei."},{"id":"D","text":"În stadiul subperiostal, durerea este localizată."},{"id":"E","text":"În stadiul submucos, intensitatea durerii scade."}],"correct":["A","D","E"],"pages":[115],"source":"set-2"},{"id":"set2-Ebnnaemg","fingerprint":"11cb23cf44099014","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"În prezența unei celulite asociate unui abces acut apical la un pacient care prezintă alergie la penicilină, schema terapeutică medicamentoasă indicată cuprinde:","options":[{"id":"A","text":"Amoxicilină 2 g/zi asociată cu metronidazol 1,5 g/zi."},{"id":"B","text":"Antialgice."},{"id":"C","text":"Clindamicină 1,2 g/zi."},{"id":"D","text":"Metronidazol 1,5 g/zi."},{"id":"E","text":"Amoxicilină și acid clavulanic 1000-2000 mg/zi."}],"correct":["B","C","D"],"pages":[115],"source":"set-2"},{"id":"set2-L96BSuT0","fingerprint":"94c57e99bf6897ef","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt condițiile care contraindică închiderea etanșă a cavității de acces după realizarea drenajului endodontic în cazul unui abces acut apical?","options":[{"id":"A","text":"Timpul insuficient pentru finalizarea procedurii."},{"id":"B","text":"Drenajul spontan al exsudatului după îndepărtarea tavanului camerei pulpare."},{"id":"C","text":"Existența unui exsudat în cantitate mare."},{"id":"D","text":"Starea generală alterată, însoțită de prezența unei tumefacții difuze."},{"id":"E","text":"Sensibilitatea dureroasă marcată."}],"correct":["A","C","D","E"],"pages":[116],"source":"set-2"},{"id":"set2-S4upOXD_","fingerprint":"0f495267ce0460ba","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Ce semne caracteristice sunt evidențiate la examenele complementare pentru un dinte afectat de abces acut apical, care nu reprezintă o acutizare a unei leziuni cronice?","options":[{"id":"A","text":"Examenul radiologic evidențiază întotdeauna o zonă extinsă de osteoliză difuză."},{"id":"B","text":"Testele de vitalitate sunt negative, iar examenul radiologic arată o zonă apicală de aspect normal sau o ușoară lărgire a ligamentului periodontal."},{"id":"C","text":"Testele de vitalitate au un răspuns exacerbat din cauza prezenței exsudatului hemoragic în canalul radicular."},{"id":"D","text":"Diagnosticul pozitiv se bazează exclusiv pe modificările osoase decelabile radiologic."},{"id":"E","text":"Testele de vitalitate sunt pozitive, reflectând inflamația pulpară acută incipientă."}],"correct":["B"],"pages":[115],"source":"set-2"},{"id":"set2-gw-7_-VD","fingerprint":"17c9e3969fa30a63","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt formele patologice incluse în clasificarea parodontitelor apicale asimptomatice (cronice)?","options":[{"id":"A","text":"Parodontita apicală cu hipercementoză"},{"id":"B","text":"Parodontita apicală fibroasă"},{"id":"C","text":"Abcesul apical acut"},{"id":"D","text":"Granulomul periapical"},{"id":"E","text":"Chistul periradicular"}],"correct":["A","B","D","E"],"pages":[116],"source":"set-2"},{"id":"set2-K0qE9KSH","fingerprint":"5e78fd61d371bf07","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Din punct de vedere histopatologic, prin ce se caracterizează parodontitele apicale asimptomatice granulomatoase?","options":[{"id":"A","text":"Proliferarea structurală a țesutului de granulație în focarul periapical."},{"id":"B","text":"Circumscrierea formațiunii de către o capsulă fibroasă, constituită din fibre de colagen atașate pe suprafața radiculară."},{"id":"C","text":"Resorbția cementului și a dentinei realizată de celule cu activitate clastică, denumite cementoclaste și dentinoclaste."},{"id":"D","text":"Prezența în țesutul de granulație a unei populații celulare de tip inflamator alcătuite predominant din neutrofile și eozinofile."},{"id":"E","text":"Resorbția rapidă a țesutului osos periapical inițiată de osteoclaste pe durata fazei asimptomatice."}],"correct":["A","B","C"],"pages":[117],"source":"set-2"},{"id":"set2-wtNpDTDG","fingerprint":"e14618b4c494ee51","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care sunt elementele anatomice de care trebuie ținut cont la realizarea diagnosticului diferențial radiologic al parodontitelor apicale asimptomatice?","options":[{"id":"A","text":"Gaura incisivă, localizată pe linia interincisivă și a cărei periferie se continuă cu spațiul periodontal."},{"id":"B","text":"Fosele nazale, caracterizate printr-o imagine de mari dimensiuni și cu un aspect oval."},{"id":"C","text":"Gaura mentonieră, care în regiunea premolarilor inferiori ia aspectul unei imagini perfect rotunde."},{"id":"D","text":"Sinusul maxilar, având convexitatea radiotransparenței îndreptată spre apexul dinților."},{"id":"E","text":"Canalul mandibular, al cărui traiect se proiectează constant ca o zonă radiotransparentă strict peste apexurile molarilor inferiori."}],"correct":["A","B","C","D"],"pages":[117],"source":"set-2"},{"id":"set2-ojPYVXQp","fingerprint":"a0a8a827068ea6ab","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este aspectul radiologic caracteristic definitoriu pentru parodontita apicală cronică fibroasă?","options":[{"id":"A","text":"Resorbție radiculară externă severă care generează o radiotransparență cu aspect tipic de fagure de miere."},{"id":"B","text":"Zonă de radiotransparență cu un contur rotund-ovalar care înconjoară apexul și depășește strict marginile rădăcinii."},{"id":"C","text":"Lărgirea spațiului periodontal apical sub formă de \"calotă\", în interiorul căreia aspectul structural osos se observă parțial păstrat."},{"id":"D","text":"Radiopacitate extinsă la nivelul apexului, care este înconjurată de un subțire halou radiotransparent."},{"id":"E","text":"Radiotransparență periapicală difuză cu pierderea completă a trabeculației osoase."}],"correct":["C"],"pages":[116],"source":"set-2"},{"id":"set2-Qcnqkt8k","fingerprint":"15d78376467004fb","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Cum se poate stabili cu certitudine diagnosticul diferențial între diversele forme granulomatoase ale parodontitelor apicale asimptomatice?","options":[{"id":"A","text":"Prin identificarea la inspecție a unei fistule active și reperarea traiectului acesteia cu un con de gutapercă steril."},{"id":"B","text":"Prin analiza matematică a ariei, formei și dimensiunii radiotransparenței prelevate pe incidențele retroalveolare."},{"id":"C","text":"Prin efectuarea examenului morfopatologic al țesuturilor vizate."},{"id":"D","text":"Prin testarea repetată a sensibilității la palparea mucoasei vestibulare în dreptul apexului radicular."},{"id":"E","text":"Prin măsurarea precisă a răspunsului fiziologic la testele de sensibilitate pulpară cu agenți termici extremi."}],"correct":["C"],"pages":[116],"source":"set-2"},{"id":"set2-mVmWZ32B","fingerprint":"f05df1cdaf99d543","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile clinice și histopatologice ale chistului periradicular?","options":[{"id":"A","text":"Este o afecțiune simptomatică în stadiile incipiente, fiind caracterizată prin teste de vitalitate pulpară intens pozitive."},{"id":"B","text":"Se clasifică în chisturi periapicale adevărate și chisturi în buzunar, acestea din urmă comunicând direct cu lumenul canalicular."},{"id":"C","text":"În stadiile avansate, palparea osului alveolar din dreptul dintelui evidențiază o consistență osoasă hipermineralizată și extrem de dură."},{"id":"D","text":"Constituie stadiul final de evoluție al unui granulom epitelial netratat."},{"id":"E","text":"Prezintă un perete conjunctiv epitelial bine constituit, care conține un epiteliu pluristratificat pavimentos."}],"correct":["B","D","E"],"pages":[117],"source":"set-2"},{"id":"set2-x-soZO9C","fingerprint":"2e8ef5a2358167d0","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care este trăsătura clinică și radiologică esențială care definește parodontita apicală condensantă?","options":[{"id":"A","text":"Radiotransparența periapicală extinsă care se continuă cu spațiul periodontal, asociată cu un dinte vital."},{"id":"B","text":"Evacuarea continuă a unui exsudat purulent printr-un traiect fistulos situat la nivelul mucoasei alveolare."},{"id":"C","text":"Prezența unei simptomatologii algice severe însoțită de tumefiere marcată și crepitație la palparea zonei apicale."},{"id":"D","text":"Formarea unei cavități încapsulate cu conținut lichidian, care determină lărgirea masivă a spațiului periodontal."},{"id":"E","text":"Evidențierea radiologică a unui os periapical hipermineralizat și îngustarea spațiului periodontal periapical la un dinte devital."}],"correct":["E"],"pages":[117],"source":"set-2"},{"id":"set2-jJr3vnIL","fingerprint":"91e5f0a4fe422704","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele localizări reprezintă căi posibile de exteriorizare a fistulei în evoluția unui abces apical cronic?","options":[{"id":"A","text":"La nivelul epiteliului pluristratificat pavimentos al peretelui intern din leziunile chistice adevărate."},{"id":"B","text":"În șanțul crevicular, unde la sondare se identifică un defect de atașament strâmt."},{"id":"C","text":"La nivelul tegumentelor."},{"id":"D","text":"La nivelul mucoasei alveolare a gingiei atașate."},{"id":"E","text":"Exclusiv în dreptul dintelui cauzal, datorită căii unice de exteriorizare prin osul alveolar."}],"correct":["B","C","D"],"pages":[118],"source":"set-2"},{"id":"set2-d3I8Q8ln","fingerprint":"1428138f88dc7a60","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce particularități clinice și etape diagnostice sunt asociate cu prezența fistulei în abcesul apical cronic?","options":[{"id":"A","text":"Inserarea unui con de gutapercă prin orificiul fistulei permite identificarea radiologică precisă a dintelui cauzal al infecției."},{"id":"B","text":"Diagnosticul diferențial al traiectului fistulos trebuie realizat cu fistulele cauzate de osteomielită, tuberculoză și actinomicoză."},{"id":"C","text":"Epitelizarea orificiului fistulos previne definitiv formarea și eliberarea ulterioară de puroi din leziunea periapicală."},{"id":"D","text":"Prezența fistulei cauzează o exacerbare a durerii din cauza acumulării masive de exsudat purulent în spațiul periodontal."},{"id":"E","text":"Închiderea spontană a fistulei generează episoade scurte de reacutizare, însoțite de tumefiere redusă și durere ușoară la atingere."}],"correct":["A","B","E"],"pages":[118],"source":"set-2"},{"id":"set2-twbHF-Hr","fingerprint":"7312e58b3bc03dea","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele proceduri și constatări aparțin conduitei terapeutice și evaluării evoluției chistului periradicular?","options":[{"id":"A","text":"Medicația intracanalară cu hidroxid de calciu este indicată atunci când nu se poate obține uscarea canalului după tratamentul mecanic și irigare."},{"id":"B","text":"Evoluția spre vindecare a afecțiunii necesită exclusiv monitorizarea imagistică, ignorând simptomatologia clinică instalată."},{"id":"C","text":"Drenarea lichidului din cavitatea chistică încetinește procesul de vindecare din cauza pierderii presiunii osmotice."},{"id":"D","text":"Tratamentul chirurgical prin chistectomie reprezintă prima intenție de tratament imediat după stabilirea diagnosticului radiologic."},{"id":"E","text":"Prezența biofilmului extraradicular periapical poate menține parodontita apicală cronică chiar și după un tratament endodontic corect."}],"correct":["A","E"],"pages":[117],"source":"set-2"},{"id":"set2-IFnxLL2I","fingerprint":"863b18dd7fce0ae6","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristicile clinice și patogenice ale parodontitei apicale cronice acutizate?","options":[{"id":"A","text":"Acutizarea se produce exclusiv în urma iritațiilor mecanice induse prin suprainstrumentare."},{"id":"B","text":"Eliberarea endotoxinelor bacteriene este în strânsă corelație cu apariția simptomatologiei acute."},{"id":"C","text":"Testele de vitalitate sunt negative, asociind durere la percuție și palpare."},{"id":"D","text":"Din punct de vedere radiologic, nu prezintă modificări decelabile din cauza rapidității cu care evoluează boala."},{"id":"E","text":"Tratamentul abordat este similar cu cel al abcesului alveolar acut."}],"correct":["B","C","E"],"pages":[119],"source":"set-2"},{"id":"set2-rEDM64OC","fingerprint":"3e2b5c7ff493415a","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Ce elemente caracterizează diagnosticul radiologic al patologiei periapicale?","options":[{"id":"A","text":"Radiotransparența periapicală este un semn clinic patognomonic cert pentru diagnosticul de parodontită apicală."},{"id":"B","text":"Parodontitele apicale simptomatice nu au ecou pe imaginea radiologică din cauza rapidității cu care evoluează forma de îmbolnăvire."},{"id":"C","text":"Procesele osteitice inițiale sunt identificabile radiologic în primele zile de la debutul inflamației."},{"id":"D","text":"Proiecția radiotransparenței pe radiografia retroalveolară este mult mai mică în dimensiune comparativ cu reprezentarea reală a leziunii osoase."},{"id":"E","text":"Lărgirea spațiului periodontal reprezintă cel mai stabil și caracteristic semn radiologic inițial."}],"correct":["B","D","E"],"pages":[119],"source":"set-2"},{"id":"set2-vt9Ak_jK","fingerprint":"b04fc34903b0d275","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Capacitatea de supraviețuire a speciei Enterococcus faecalis și implicarea sa în eșecul tratamentului endodontic se datorează următoarelor mecanisme:","options":[{"id":"A","text":"Dependenței stricte de nutrienții furnizați de alte bacterii prezente în lanțurile nutritive microbiene."},{"id":"B","text":"Abilității de a pătrunde în profunzimea tubulilor dentinari pe fondul dimensiunilor sale reduse."},{"id":"C","text":"Organizării sub forma unui biofilm dens, realizată prin colonizarea pereților canalului radicular."},{"id":"D","text":"Capacității de a se adapta la condițiile nefavorabile de mediu prin reglarea expresiei genice."},{"id":"E","text":"Sensibilității crescute la acțiunea hidroxidului de calciu utilizat ca medicație intracanaliculară temporară."}],"correct":["B","C","D"],"pages":[120],"source":"set-2"},{"id":"set2-_gjY0ETE","fingerprint":"1be1be7dd0d413a2","chapterId":"set-2","subchapterId":"set2-2.02","type":"CM","text":"Care dintre următoarele aspecte descriu caracteristicile infecțiilor extraradiculare și ale biofilmului bacterian endodontic?","options":[{"id":"A","text":"Matricea polimerică a biofilmului bacterian este constituită exclusiv din lipide și ioni de calciu mineralizați."},{"id":"B","text":"Primele celule extravazate care migrează spre zona inflamației periapicale sunt leucocitele neutrofile polimorfonucleare."},{"id":"C","text":"Speciile de Actinomyces și Propionibacterium sunt izolate frecvent din patologia extraradiculară."},{"id":"D","text":"Veziculele extracelulare bacteriene prezintă aceeași determinanță antigenică precum bacteria parentală, contribuind la rezistența germenilor."},{"id":"E","text":"Infecția extraradiculară se dezvoltă exclusiv dependent de infecția intraradiculară preexistentă."}],"correct":["B","C","D"],"pages":[121],"source":"set-2"},{"id":"set2-eTFtGzy_","fingerprint":"fd735adecad49970","chapterId":"set-2","subchapterId":"set2-2.02","type":"CS","text":"Care dintre următoarele caracteristici definește în mod specific infecția endodontică secundară?","options":[{"id":"A","text":"Constituie inflamația inițială provocată de microorganismele care colonizează pentru prima oară țesutul pulpar necrotic."},{"id":"B","text":"Nu include specii fungice, fiind dominată exclusiv de flora bacteriană gram-negativă strict anaerobă."},{"id":"C","text":"Este formată constant dintr-o floră microbiană diversificată de aproximativ 20 de specii bacteriene periapicale."},{"id":"D","text":"Dezvoltarea acesteia este stopată definitiv prin îndepărtarea formelor microbiene planctonice în timpul irigării canalare."},{"id":"E","text":"Este generată de microorganisme care pătrund în canalul radicular în timpul tratamentului, între ședințe sau la finalizarea acestuia."}],"correct":["E"],"pages":[120],"source":"set-2"}];
